const t="73Ie2Kya2iE",e="73Ie2Kya2iE",a="Real Conversation About Your Day | Intermediate English Speaking Practice (A2–B1)",n="Mr. English Channel",d="A2",o="Kể chuyện trong ngày",l=18,h=837,r="auto",s=JSON.parse(`[{"start":8.36,"end":10.88,"text":"Hello everyone and welcome back to Mr.","words":[["Hello",8.36],["everyone",8.64],["and",9.32],["welcome",9.56],["back",9.92],["to",10.24],["Mr.",10.4]],"ipa":"/həˈloʊ ˈɛvriˌwʌn ənd ˈwɛlkəm bæk tu ˈmɪstər/"},{"start":10.88,"end":17.6,"text":"English Channel where learning English is easy and fun. I'm Emily. Hello Emily. Hi everyone.","words":[["English",10.88],["Channel",11.24],["where",11.96],["learning",12.2],["English",12.6],["is",13.08],["easy",13.36],["and",13.76],["fun.",13.96],["I'm",14.64],["Emily.",14.88],["Hello",15.6],["Emily.",15.92],["Hi",16.36],["everyone.",16.6]],"ipa":"/ˈɪŋɡlɪʃ ˈtʃænəl wɛr ˈlɝnɪŋ ˈɪŋɡlɪʃ ɪz ˈizi ənd fʌn aɪm ˈɛmɪli həˈloʊ ˈɛmɪli haɪ ˈɛvriˌwʌn/"},{"start":17.6,"end":19.08,"text":"It's good to have you here.","words":[["It's",17.6],["good",17.76],["to",17.92],["have",18],["you",18.16],["here.",18.24]],"ipa":"/ɪts ɡʊd tu hæv ju hir/"},{"start":19.08,"end":22.24,"text":"Emily, I've got a very ordinary question for you today.","words":[["Emily,",19.08],["I've",19.48],["got",19.64],["a",19.8],["very",19.84],["ordinary",20.36],["question",20.96],["for",21.4],["you",21.52],["today.",21.64]],"ipa":"/ˈɛmɪli aɪv ɡɑt ə ˈvɛri ˈɔrdəˌnɛri ˈkwɛstʃən fɔr ju təˈdeɪ/"},{"start":22.24,"end":23.4,"text":"How's your day been?","words":[["How's",22.24],["your",22.4],["day",22.48],["been?",22.64]],"ipa":"/haʊz jɔr deɪ bɪn/"},{"start":23.4,"end":26.48,"text":"Honestly, a little hectic, but better now.","words":[["Honestly,",23.4],["a",24.28],["little",24.36],["hectic,",24.64],["but",25.2],["better",25.56],["now.",25.8]],"ipa":"/ˈɑnəstli ə ˈlɪtəl ˈhɛktɪk bʌt ˈbɛtər naʊ/"},{"start":26.48,"end":31.96,"text":"I left the house feeling organized and about 10 minutes later that feeling disappeared.","words":[["I",26.48],["left",26.6],["the",26.92],["house",27],["feeling",27.36],["organized",27.72],["and",28.36],["about",28.64],["10",29],["minutes",29.28],["later",29.6],["that",30.32],["feeling",30.56],["disappeared.",30.96]],"ipa":"/aɪ lɛft ðə haʊs ˈfilɪŋ ˈɔrɡəˌnaɪzd ənd əˈbaʊt ˈmɪnəts ˈleɪtər ðæt ˈfilɪŋ ˌdɪsəˈpɪrd/"},{"start":31.96,"end":33.76,"text":"Oh, well what happened?","words":[["Oh,",31.96],["well",32.68],["what",32.8],["happened?",32.96]],"ipa":"/oʊ wɛl wʌt ˈhæpənd/"},{"start":33.76,"end":38.36,"text":"Because 10 minutes is a pretty short life for a feeling that good.","words":[["Because",33.76],["10",34.08],["minutes",34.28],["is",34.6],["a",34.72],["pretty",34.76],["short",35],["life",35.36],["for",35.68],["a",35.8],["feeling",35.88],["that",36.2],["good.",36.4]],"ipa":"/bɪˈkɔz ˈmɪnəts ɪz ə ˈprɪti ʃɔrt laɪf fɔr ə ˈfilɪŋ ðæt ɡʊd/"},{"start":38.36,"end":42.12,"text":"I realized I'd brought my lunch but left my work bag at home.","words":[["I",38.36],["realized",38.48],["I'd",39.12],["brought",39.28],["my",39.56],["lunch",39.68],["but",40.12],["left",40.32],["my",40.6],["work",40.76],["bag",41],["at",41.28],["home.",41.4]],"ipa":"/aɪ ˈriəˌlaɪzd aɪd brɔt maɪ lʌntʃ bʌt lɛft maɪ wɝk bæɡ æt hoʊm/"},{"start":42.12,"end":45.64,"text":"Apparently, I was prepared to eat but not prepared to teach.","words":[["Apparently,",42.12],["I",42.72],["was",42.84],["prepared",43],["to",43.4],["eat",43.52],["but",43.84],["not",44.12],["prepared",44.44],["to",44.8],["teach.",44.88]],"ipa":"/əˈpɛrəntli aɪ wɑz priˈpɛrd tu it bʌt nɑt priˈpɛrd tu titʃ/"},{"start":45.64,"end":47.88,"text":"Well, you had your priorities.","words":[["Well,",45.64],["you",46.2],["had",46.32],["your",46.44],["priorities.",46.56]],"ipa":"/wɛl ju hæd jɔr praɪˈɔrətiz/"},{"start":47.88,"end":51.36,"text":"Did you have to go all the way back or could someone bring it to you?","words":[["Did",47.88],["you",48.12],["have",48.2],["to",48.32],["go",48.44],["all",48.6],["the",48.8],["way",48.88],["back",49.04],["or",49.48],["could",49.76],["someone",49.96],["bring",50.24],["it",50.44],["to",50.56],["you?",50.64]],"ipa":"/dɪd ju hæv tu ɡoʊ ɔl ðə weɪ bæk ɔr kʊd ˈsʌmˌwʌn brɪŋ ɪt tu ju/"},{"start":51.36,"end":52.4,"text":"I went back.","words":[["I",51.36],["went",51.52],["back.",51.76]],"ipa":"/aɪ wɛnt bæk/"},{"start":52.4,"end":58.16,"text":"Luckily, I hadn't gotten very far, but that little mistake made the whole morning feel rushed.","words":[["Luckily,",52.4],["I",52.96],["hadn't",53.08],["gotten",53.36],["very",53.64],["far,",53.92],["but",54.56],["that",54.72],["little",54.96],["mistake",55.28],["made",55.84],["the",56.08],["whole",56.2],["morning",56.6],["feel",56.96],["rushed.",57.32]],"ipa":"/ˈlʌkəli aɪ ˈhædənt ˈɡɑtən ˈvɛri fɑr bʌt ðæt ˈlɪtəl mɪˈsteɪk meɪd ðə hoʊl ˈmɔrnɪŋ fil rʌʃt/"},{"start":58.16,"end":59.04,"text":"What about you?","words":[["What",58.16],["about",58.32],["you?",58.52]],"ipa":"/wʌt əˈbaʊt ju/"},{"start":59.04,"end":60.84,"text":"How's your day been so far?","words":[["How's",59.04],["your",59.28],["day",59.44],["been",59.64],["so",59.88],["far?",60.04]],"ipa":"/haʊz jɔr deɪ bɪn soʊ fɑr/"},{"start":60.84,"end":63.68,"text":"Pretty good actually. Nothing exciting.","words":[["Pretty",60.84],["good",61.16],["actually.",61.6],["Nothing",62.32],["exciting.",62.6]],"ipa":"/ˈprɪti ɡʊd ˈækˌtʃuəli ˈnʌθɪŋ ɪkˈsaɪtɪŋ/"},{"start":63.68,"end":68.56,"text":"Although now that you've told me your story, pretty good feels like a very small answer.","words":[["Although",63.68],["now",64.08],["that",64.32],["you've",64.44],["told",64.6],["me",64.84],["your",64.96],["story,",65.2],["pretty",65.8],["good",66.12],["feels",66.56],["like",66.84],["a",66.96],["very",67.04],["small",67.32],["answer.",67.8]],"ipa":"/ˌɔlˈðoʊ naʊ ðæt juv toʊld mi jɔr ˈstɔri ˈprɪti ɡʊd filz laɪk ə ˈvɛri smɔl ˈænsər/"},{"start":68.56,"end":72.76,"text":"It's a perfectly normal answer, but you've closed the door a little.","words":[["It's",68.56],["a",68.8],["perfectly",68.88],["normal",69.52],["answer,",69.96],["but",70.72],["you've",70.92],["closed",71.16],["the",71.64],["door",71.76],["a",72],["little.",72.04]],"ipa":"/ɪts ə ˈpɝfəktli ˈnɔrməl ˈænsər bʌt juv kloʊzd ðə dɔr ə ˈlɪtəl/"},{"start":72.76,"end":78.28,"text":"I don't know whether to ask about your work, your morning, or something else. That's fair.","words":[["I",72.76],["don't",72.88],["know",73.08],["whether",73.2],["to",73.48],["ask",73.6],["about",73.88],["your",74.16],["work,",74.32],["your",74.92],["morning,",75.08],["or",75.6],["something",75.88],["else.",76.24],["That's",76.96],["fair.",77.4]],"ipa":"/aɪ doʊnt noʊ ˈwɛðər tu æsk əˈbaʊt jɔr wɝk jɔr ˈmɔrnɪŋ ɔr ˈsʌmθɪŋ ɛls ðæts fɛr/"},{"start":78.28,"end":80.6,"text":"Let me open it again. Pretty good.","words":[["Let",78.28],["me",78.44],["open",78.56],["it",78.8],["again.",78.92],["Pretty",79.8],["good.",80.08]],"ipa":"/lɛt mi ˈoʊpən ɪt əˈɡɛn ˈprɪti ɡʊd/"},{"start":80.6,"end":84.84,"text":"I finally finished something I'd been putting off all week, so I'm feeling lighter.","words":[["I",80.6],["finally",80.72],["finished",81.16],["something",81.56],["I'd",81.92],["been",82.04],["putting",82.2],["off",82.48],["all",82.72],["week,",82.88],["so",83.16],["I'm",83.56],["feeling",83.68],["lighter.",83.96]],"ipa":"/aɪ ˈfaɪnəli ˈfɪnɪʃt ˈsʌmθɪŋ aɪd bɪn ˈpʌtɪŋ ɔf ɔl wik soʊ aɪm ˈfilɪŋ ˈlaɪtər/"},{"start":84.84,"end":87.16,"text":"Oh, that gives me something to ask about.","words":[["Oh,",84.84],["that",85.16],["gives",85.44],["me",85.68],["something",85.8],["to",86.12],["ask",86.24],["about.",86.44]],"ipa":"/oʊ ðæt ɡɪvz mi ˈsʌmθɪŋ tu æsk əˈbaʊt/"},{"start":87.16,"end":88.8,"text":"What had you been putting off?","words":[["What",87.16],["had",87.36],["you",87.52],["been",87.6],["putting",87.76],["off?",88.08]],"ipa":"/wʌt hæd ju bɪn ˈpʌtɪŋ ɔf/"},{"start":88.8,"end":91.44,"text":"Sorting out a problem with my internet bill.","words":[["Sorting",88.8],["out",89.24],["a",89.36],["problem",89.4],["with",89.84],["my",89.96],["internet",90.16],["bill.",90.56]],"ipa":"/ˈsɔrtɪŋ aʊt ə ˈprɑbləm wɪð maɪ ˈɪntərˌnɛt bɪl/"},{"start":91.44,"end":93.48,"text":"I kept thinking the call would take an hour.","words":[["I",91.44],["kept",91.52],["thinking",91.8],["the",92.12],["call",92.2],["would",92.48],["take",92.6],["an",92.8],["hour.",92.92]],"ipa":"/aɪ kɛpt ˈθɪŋkɪŋ ðə kɔl wʊd teɪk æn ˈaʊər/"},{"start":93.48,"end":95.04,"text":"It took 12 minutes.","words":[["It",93.48],["took",93.64],["12",93.88],["minutes.",94.32]],"ipa":"/ɪt tʊk ˈmɪnəts/"},{"start":95.04,"end":97.44,"text":"Avoiding it took considerably longer.","words":[["Avoiding",95.04],["it",95.48],["took",95.64],["considerably",95.84],["longer.",96.48]],"ipa":"/əˈvɔɪdɪŋ ɪt tʊk kənˈsɪdərəbli ˈlɔŋɡər/"},{"start":97.44,"end":98.76,"text":"I know that feeling.","words":[["I",97.44],["know",97.6],["that",97.8],["feeling.",98.04]],"ipa":"/aɪ noʊ ðæt ˈfilɪŋ/"},{"start":98.76,"end":105.92,"text":"The task lives in your head, follows you into dinner, and somehow gets bigger every time you ignore it. Exactly.","words":[["The",98.76],["task",98.88],["lives",99.4],["in",99.72],["your",99.84],["head,",100],["follows",100.6],["you",101.12],["into",101.24],["dinner,",101.48],["and",101.88],["somehow",102.08],["gets",102.52],["bigger",102.8],["every",103.24],["time",103.6],["you",103.88],["ignore",104],["it.",104.4],["Exactly.",105]],"ipa":"/ðə tæsk lɪvz ɪn jɔr hɛd ˈfɑloʊz ju ˈɪntu ˈdɪnər ənd ˈsʌmˌhaʊ ɡɛts ˈbɪɡər ˈɛvəri taɪm ju ˌɪɡˈnɔr ɪt ɪɡˈzæktli/"},{"start":105.92,"end":108.44,"text":"And that's the real story of my morning.","words":[["And",105.92],["that's",106.16],["the",106.52],["real",106.64],["story",106.96],["of",107.32],["my",107.4],["morning.",107.52]],"ipa":"/ənd ðæts ðə ril ˈstɔri ʌv maɪ ˈmɔrnɪŋ/"},{"start":108.44,"end":113.28,"text":"I didn't do anything impressive, but I stopped carrying around this annoying little worry.","words":[["I",108.44],["didn't",108.52],["do",108.8],["anything",108.96],["impressive,",109.28],["but",110],["I",110.28],["stopped",110.36],["carrying",110.76],["around",111.16],["this",111.56],["annoying",111.72],["little",112.16],["worry.",112.4]],"ipa":"/aɪ ˈdɪdənt du ˈɛniˌθɪŋ ˌɪmˈprɛsɪv bʌt aɪ stɑpt ˈkæriɪŋ ərˈaʊnd ðɪs əˈnɔɪɪŋ ˈlɪtəl ˈwɝi/"},{"start":113.28,"end":116.64,"text":"Which is much more interesting than a list of things you did.","words":[["Which",113.28],["is",113.56],["much",113.76],["more",114.16],["interesting",114.36],["than",114.88],["a",115.04],["list",115.08],["of",115.4],["things",115.52],["you",115.84],["did.",115.96]],"ipa":"/wɪtʃ ɪz mʌtʃ mɔr ˈɪntrəstɪŋ ðæn ə lɪst ʌv θɪŋz ju dɪd/"},{"start":116.64,"end":122.52,"text":"When someone asks about your day, they're often asking what stood out, not requesting your schedule.","words":[["When",116.64],["someone",116.88],["asks",117.28],["about",117.64],["your",117.88],["day,",118],["they're",118.64],["often",118.88],["asking",119.24],["what",119.72],["stood",119.92],["out,",120.24],["not",120.64],["requesting",120.88],["your",121.48],["schedule.",121.64]],"ipa":"/wɛn ˈsʌmˌwʌn æsks əˈbaʊt jɔr deɪ ðɛr ˈɔfən ˈæskɪŋ wʌt stʊd aʊt nɑt rɪˈkwɛstɪŋ jɔr ˈskɛdʒʊl/"},{"start":122.52,"end":125.48,"text":"Although, sometimes I genuinely want the schedule.","words":[["Although,",122.52],["sometimes",123.04],["I",123.64],["genuinely",123.76],["want",124.44],["the",124.72],["schedule.",124.8]],"ipa":"/ˌɔlˈðoʊ səmˈtaɪmz aɪ ˈdʒɛnjəwənli wɑnt ðə ˈskɛdʒʊl/"},{"start":125.48,"end":130.24,"text":"If my friend says they spent the whole day moving apartments, I want to hear how that went.","words":[["If",125.48],["my",125.64],["friend",125.8],["says",126.16],["they",126.4],["spent",126.52],["the",126.8],["whole",126.88],["day",127.08],["moving",127.24],["apartments,",127.64],["I",128.48],["want",128.6],["to",128.8],["hear",128.88],["how",129.12],["that",129.24],["went.",129.44]],"ipa":"/ɪf maɪ frɛnd sɛz ðeɪ spɛnt ðə hoʊl deɪ ˈmuvɪŋ əˈpɑrtmənts aɪ wɑnt tu hir haʊ ðæt wɛnt/"},{"start":130.24,"end":133.04,"text":"Sure, because there's already a story there.","words":[["Sure,",130.24],["because",130.8],["there's",131.08],["already",131.4],["a",131.84],["story",131.92],["there.",132.36]],"ipa":"/ʃʊr bɪˈkɔz ðɛrz ɔlˈrɛdi ə ˈstɔri ðɛr/"},{"start":133.04,"end":136.56,"text":"But even then, I'd probably start with a surprising part.","words":[["But",133.04],["even",133.28],["then,",133.56],["I'd",133.88],["probably",134.12],["start",134.6],["with",134.88],["a",135.04],["surprising",135.08],["part.",135.8]],"ipa":"/bʌt ˈivɪn ðɛn aɪd ˈprɑbəˌbli stɑrt wɪð ə sərˈpraɪzɪŋ pɑrt/"},{"start":136.56,"end":140.16,"text":"We got everything moved, but the couch almost didn't fit.","words":[["We",136.56],["got",136.72],["everything",137],["moved,",137.44],["but",137.92],["the",138.16],["couch",138.24],["almost",138.72],["didn't",139.08],["fit.",139.4]],"ipa":"/wi ɡɑt ˈɛvriˌθɪŋ muvd bʌt ðə kaʊtʃ ˈɔlˌmoʊst ˈdɪdənt fɪt/"},{"start":140.16,"end":142.48,"text":"And immediately I'm wondering about the couch.","words":[["And",140.16],["immediately",140.36],["I'm",141],["wondering",141.2],["about",141.6],["the",141.84],["couch.",141.92]],"ipa":"/ənd ˌɪˈmiˌdiətli aɪm ˈwʌndərɪŋ əˈbaʊt ðə kaʊtʃ/"},{"start":142.48,"end":143.8,"text":"Did you measure the doorway?","words":[["Did",142.48],["you",142.68],["measure",142.8],["the",143.08],["doorway?",143.2]],"ipa":"/dɪd ju ˈmɛʒər ðə ˈdɔrˌweɪ/"},{"start":143.8,"end":145.12,"text":"Did someone get stuck?","words":[["Did",143.8],["someone",143.96],["get",144.24],["stuck?",144.4]],"ipa":"/dɪd ˈsʌmˌwʌn ɡɛt stʌk/"},{"start":145.12,"end":147.56,"text":"Is the couch still outside? Right.","words":[["Is",145.12],["the",145.28],["couch",145.36],["still",145.6],["outside?",145.84],["Right.",146.92]],"ipa":"/ɪz ðə kaʊtʃ stɪl ˈaʊtˈsaɪd raɪt/"},{"start":147.56,"end":150.44,"text":"One detail creates a reason to keep talking.","words":[["One",147.56],["detail",147.88],["creates",148.36],["a",148.8],["reason",148.88],["to",149.28],["keep",149.4],["talking.",149.64]],"ipa":"/wʌn dɪˈteɪl kriˈeɪts ə ˈrizən tu kip ˈtɔkɪŋ/"},{"start":150.44,"end":155.44,"text":"You don't need an extraordinary day, you just need a moment the other person can picture.","words":[["You",150.44],["don't",150.56],["need",150.8],["an",151.08],["extraordinary",151.2],["day,",151.96],["you",152.52],["just",152.64],["need",152.92],["a",153.12],["moment",153.16],["the",153.6],["other",153.76],["person",154],["can",154.44],["picture.",154.6]],"ipa":"/ju doʊnt nid æn ˌɛkstrəˈɔrdəˌnɛri deɪ ju dʒʌst nid ə ˈmoʊmənt ðə ˈʌðər ˈpɝsən kæn ˈpɪktʃər/"},{"start":155.44,"end":160.2,"text":"So, suppose my actual morning was coffee, emails, and a meeting.","words":[["So,",155.44],["suppose",156.04],["my",156.56],["actual",156.76],["morning",157.2],["was",157.6],["coffee,",157.76],["emails,",158.48],["and",159.16],["a",159.28],["meeting.",159.36]],"ipa":"/soʊ səˈpoʊz maɪ ˈæktʃəwəl ˈmɔrnɪŋ wɑz ˈkɑfi iˈmeɪlz ənd ə ˈmitɪŋ/"},{"start":160.2,"end":163.6,"text":"How do I talk about that without pretending it was an adventure?","words":[["How",160.2],["do",160.32],["I",160.48],["talk",160.52],["about",160.8],["that",161.12],["without",161.48],["pretending",161.76],["it",162.28],["was",162.4],["an",162.6],["adventure?",162.68]],"ipa":"/haʊ du aɪ tɔk əˈbaʊt ðæt wɪˈθaʊt priˈtɛndɪŋ ɪt wɑz æn ædˈvɛntʃər/"},{"start":163.6,"end":165,"text":"What was the meeting like?","words":[["What",163.6],["was",163.8],["the",163.92],["meeting",164.04],["like?",164.4]],"ipa":"/wʌt wɑz ðə ˈmitɪŋ laɪk/"},{"start":165,"end":166.44,"text":"Did anything change?","words":[["Did",165],["anything",165.28],["change?",165.64]],"ipa":"/dɪd ˈɛniˌθɪŋ tʃeɪndʒ/"},{"start":166.44,"end":171.6,"text":"Did you leave feeling relieved, confused, or ready for lunch? Mostly relieved.","words":[["Did",166.44],["you",166.6],["leave",166.72],["feeling",167.04],["relieved,",167.44],["confused,",168.16],["or",168.92],["ready",169.16],["for",169.44],["lunch?",169.56],["Mostly",170.48],["relieved.",170.88]],"ipa":"/dɪd ju liv ˈfilɪŋ rɪˈlivd kənfˈjuzd ɔr ˈrɛdi fɔr lʌntʃ ˈmoʊstli rɪˈlivd/"},{"start":171.6,"end":175.56,"text":"We agreed to move a deadline, so it gave everyone a little breathing room.","words":[["We",171.6],["agreed",171.76],["to",172.12],["move",172.2],["a",172.44],["deadline,",172.48],["so",173.08],["it",173.44],["gave",173.56],["everyone",173.72],["a",174.12],["little",174.16],["breathing",174.4],["room.",174.8]],"ipa":"/wi əˈɡrid tu muv ə ˈdɛdˌlaɪn soʊ ɪt ɡeɪv ˈɛvriˌwʌn ə ˈlɪtəl ˈbriðɪŋ rum/"},{"start":175.56,"end":177.24,"text":"Then, there's your answer.","words":[["Then,",175.56],["there's",175.92],["your",176.2],["answer.",176.36]],"ipa":"/ðɛn ðɛrz jɔr ˈænsər/"},{"start":177.24,"end":182.04,"text":"It's been a busy morning, but we moved a deadline, so the afternoon should be easier.","words":[["It's",177.24],["been",177.44],["a",177.6],["busy",177.68],["morning,",178.04],["but",178.48],["we",178.76],["moved",178.92],["a",179.28],["deadline,",179.32],["so",179.88],["the",180.12],["afternoon",180.28],["should",180.84],["be",181.04],["easier.",181.2]],"ipa":"/ɪts bɪn ə ˈbɪzi ˈmɔrnɪŋ bʌt wi muvd ə ˈdɛdˌlaɪn soʊ ðə ˌæftərˈnun ʃʊd bi ˈiziər/"},{"start":182.04,"end":184.16,"text":"That sounds like a person talking.","words":[["That",182.04],["sounds",182.28],["like",182.6],["a",182.72],["person",182.8],["talking.",183.28]],"ipa":"/ðæt saʊndz laɪk ə ˈpɝsən ˈtɔkɪŋ/"},{"start":184.16,"end":187.36,"text":"It does, and breathing room is useful here.","words":[["It",184.16],["does,",184.32],["and",184.96],["breathing",185.32],["room",185.84],["is",186],["useful",186.16],["here.",186.52]],"ipa":"/ɪt dʌz ənd ˈbriðɪŋ rum ɪz ˈjusfəl hir/"},{"start":187.36,"end":191.84,"text":"I don't mean extra space in the office, I mean a little more time and less pressure.","words":[["I",187.36],["don't",187.44],["mean",187.68],["extra",187.96],["space",188.28],["in",188.6],["the",188.68],["office,",188.8],["I",189.32],["mean",189.44],["a",189.8],["little",189.84],["more",190.08],["time",190.28],["and",190.68],["less",190.8],["pressure.",190.96]],"ipa":"/aɪ doʊnt min ˈɛkstrə speɪs ɪn ðə ˈɔfɪs aɪ min ə ˈlɪtəl mɔr taɪm ənd lɛs ˈprɛʃər/"},{"start":191.84,"end":194.56,"text":"Would you say that to someone you just met though?","words":[["Would",191.84],["you",192],["say",192.12],["that",192.28],["to",192.52],["someone",192.64],["you",193.12],["just",193.32],["met",193.68],["though?",193.96]],"ipa":"/wʊd ju seɪ ðæt tu ˈsʌmˌwʌn ju dʒʌst mɛt ðoʊ/"},{"start":194.56,"end":198.76,"text":"Or would you keep the work details shorter? Shorter, probably.","words":[["Or",194.56],["would",194.76],["you",194.92],["keep",195.04],["the",195.32],["work",195.44],["details",195.72],["shorter?",196.24],["Shorter,",197.16],["probably.",197.76]],"ipa":"/ɔr wʊd ju kip ðə wɝk dɪˈteɪlz ˈʃɔrtər ˈʃɔrtər ˈprɑbəˌbli/"},{"start":198.76,"end":200.76,"text":"Busy, but things are settling down.","words":[["Busy,",198.76],["but",199.2],["things",199.44],["are",199.72],["settling",199.8],["down.",200.2]],"ipa":"/ˈbɪzi bʌt θɪŋz ɑr ˈsɛtəlɪŋ daʊn/"},{"start":200.76,"end":205,"text":"With a close friend, I might explain why that deadline had been stressing me out.","words":[["With",200.76],["a",200.88],["close",200.92],["friend,",201.28],["I",201.76],["might",201.84],["explain",202.08],["why",202.48],["that",202.68],["deadline",202.96],["had",203.4],["been",203.56],["stressing",203.72],["me",204.12],["out.",204.28]],"ipa":"/wɪð ə kloʊs frɛnd aɪ maɪt ɪkˈspleɪn waɪ ðæt ˈdɛdˌlaɪn hæd bɪn ˈstrɛsɪŋ mi aʊt/"},{"start":205,"end":206.04,"text":"That makes sense.","words":[["That",205],["makes",205.12],["sense.",205.36]],"ipa":"/ðæt meɪks sɛns/"},{"start":206.04,"end":208.68,"text":"The relationship helps you choose the detail.","words":[["The",206.04],["relationship",206.16],["helps",206.88],["you",207.16],["choose",207.28],["the",207.68],["detail.",207.8]],"ipa":"/ðə riˈleɪʃənˌʃɪp hɛlps ju tʃuz ðə dɪˈteɪl/"},{"start":208.68,"end":213.08,"text":"My neighbor probably doesn't need the full history of my missing work bag.","words":[["My",208.68],["neighbor",208.84],["probably",209.24],["doesn't",209.84],["need",210.2],["the",210.36],["full",210.48],["history",210.92],["of",211.52],["my",211.64],["missing",211.8],["work",212.2],["bag.",212.44]],"ipa":"/maɪ ˈneɪbər ˈprɑbəˌbli ˈdʌzənt nid ðə fʊl ˈhɪstəri ʌv maɪ ˈmɪsɪŋ wɝk bæɡ/"},{"start":213.08,"end":218.2,"text":"Unless your neighbor found it, then the bag becomes very relevant. True.","words":[["Unless",213.08],["your",213.44],["neighbor",213.56],["found",213.88],["it,",214.24],["then",214.56],["the",214.8],["bag",214.88],["becomes",215.12],["very",215.52],["relevant.",215.8],["True.",217.2]],"ipa":"/ənˈlɛs jɔr ˈneɪbər faʊnd ɪt ðɛn ðə bæɡ bɪˈkʌmz ˈvɛri ˈrɛləvənt tru/"},{"start":218.2,"end":221.72,"text":"Now, once you've chosen a moment, there's another challenge.","words":[["Now,",218.2],["once",218.6],["you've",218.88],["chosen",219.04],["a",219.48],["moment,",219.52],["there's",220.12],["another",220.44],["challenge.",220.8]],"ipa":"/naʊ wʌns juv ˈtʃoʊzən ə ˈmoʊmənt ðɛrz əˈnʌðər ˈtʃæləndʒ/"},{"start":221.72,"end":226,"text":"How do you tell the story without getting lost in all the little steps?","words":[["How",221.72],["do",221.88],["you",222],["tell",222.12],["the",222.4],["story",222.48],["without",222.88],["getting",223.28],["lost",223.64],["in",224.08],["all",224.28],["the",224.48],["little",224.6],["steps?",224.84]],"ipa":"/haʊ du ju tɛl ðə ˈstɔri wɪˈθaʊt ˈɡɛtɪŋ lɔst ɪn ɔl ðə ˈlɪtəl stɛps/"},{"start":226,"end":230,"text":"I usually start talking and discover that problem halfway through.","words":[["I",226],["usually",226.16],["start",226.6],["talking",226.96],["and",227.44],["discover",227.6],["that",228],["problem",228.24],["halfway",228.64],["through.",229.04]],"ipa":"/aɪ ˈjuʒəwəli stɑrt ˈtɔkɪŋ ənd dɪˈskʌvər ðæt ˈprɑbləm ˈhæfˈweɪ θru/"},{"start":230,"end":234.76,"text":"Suddenly I'm explaining where I parked, and even I don't know why it matters.","words":[["Suddenly",230],["I'm",230.44],["explaining",230.56],["where",231.12],["I",231.4],["parked,",231.52],["and",232.12],["even",232.32],["I",232.64],["don't",232.72],["know",232.96],["why",233.16],["it",233.32],["matters.",233.44]],"ipa":"/ˈsʌdənli aɪm ɪkˈspleɪnɪŋ wɛr aɪ pɑrkt ənd ˈivɪn aɪ doʊnt noʊ waɪ ɪt ˈmætərz/"},{"start":234.76,"end":235.92,"text":"I've done that.","words":[["I've",234.76],["done",234.96],["that.",235.2]],"ipa":"/aɪv dʌn ðæt/"},{"start":235.92,"end":239.12,"text":"It helps to give the listener a simple starting point.","words":[["It",235.92],["helps",236.12],["to",236.36],["give",236.48],["the",236.72],["listener",236.8],["a",237.36],["simple",237.48],["starting",237.96],["point.",238.4]],"ipa":"/ɪt hɛlps tu ɡɪv ðə ˈlɪsənər ə ˈsɪmpəl ˈstɑrtɪŋ pɔɪnt/"},{"start":239.12,"end":242.96,"text":"I was on my way to work when I realized I'd forgotten my bag.","words":[["I",239.12],["was",239.2],["on",239.4],["my",239.52],["way",239.64],["to",239.8],["work",239.92],["when",240.32],["I",240.68],["realized",240.8],["I'd",241.4],["forgotten",241.52],["my",241.92],["bag.",242.08]],"ipa":"/aɪ wɑz ɑn maɪ weɪ tu wɝk wɛn aɪ ˈriəˌlaɪzd aɪd fərˈɡɑtən maɪ bæɡ/"},{"start":242.96,"end":244.88,"text":"That gets us straight into the problem.","words":[["That",242.96],["gets",243.32],["us",243.56],["straight",243.64],["into",243.92],["the",244.08],["problem.",244.2]],"ipa":"/ðæt ɡɛts ʌs streɪt ˈɪntu ðə ˈprɑbləm/"},{"start":244.88,"end":250.68,"text":"You don't have to begin with your alarm going off unless the alarm caused the problem. Exactly.","words":[["You",244.88],["don't",245.04],["have",245.28],["to",245.52],["begin",245.6],["with",246],["your",246.16],["alarm",246.28],["going",246.72],["off",247],["unless",247.28],["the",247.72],["alarm",247.84],["caused",248.24],["the",248.68],["problem.",248.76],["Exactly.",249.72]],"ipa":"/ju doʊnt hæv tu bɪˈɡɪn wɪð jɔr əˈlɑrm ˈɡoʊɪŋ ɔf ənˈlɛs ðə əˈlɑrm kɑzd ðə ˈprɑbləm ɪɡˈzæktli/"},{"start":250.68,"end":256.24,"text":"Then I can add, \\"So, I turned around, picked it up, and got there just before my first class.\\"","words":[["Then",250.68],["I",250.96],["can",251.04],["add,",251.2],["\\"So,",251.68],["I",252.12],["turned",252.2],["around,",252.52],["picked",253.12],["it",253.36],["up,",253.48],["and",253.8],["got",254],["there",254.24],["just",254.48],["before",254.8],["my",255.08],["first",255.2],["class.\\"",255.48]],"ipa":"/ðɛn aɪ kæn æd soʊ aɪ tɝnd ərˈaʊnd pɪkt ɪt ʌp ənd ɡɑt ðɛr dʒʌst bɪˈfɔr maɪ fɝst klæs/"},{"start":256.24,"end":258.44,"text":"The listener can follow what happened.","words":[["The",256.24],["listener",256.36],["can",256.76],["follow",256.96],["what",257.28],["happened.",257.44]],"ipa":"/ðə ˈlɪsənər kæn ˈfɑloʊ wʌt ˈhæpənd/"},{"start":258.44,"end":263.2,"text":"And if I want the earlier background, I can ask, \\"Were you running late already?\\"","words":[["And",258.44],["if",258.76],["I",258.96],["want",259.04],["the",259.28],["earlier",259.48],["background,",259.92],["I",260.52],["can",260.6],["ask,",260.8],["\\"Were",261.36],["you",261.6],["running",261.76],["late",262.08],["already?\\"",262.32]],"ipa":"/ənd ɪf aɪ wɑnt ðə ˈɝliər ˈbækˌɡraʊnd aɪ kæn æsk wɝ ju ˈrʌnɪŋ leɪt ɔlˈrɛdi/"},{"start":263.2,"end":266.96,"text":"You don't have to answer every possible question before I've asked one.","words":[["You",263.2],["don't",263.32],["have",263.52],["to",263.68],["answer",263.84],["every",264.2],["possible",264.48],["question",264.96],["before",265.44],["I've",265.8],["asked",265.92],["one.",266.2]],"ipa":"/ju doʊnt hæv tu ˈænsər ˈɛvəri ˈpɑsəbəl ˈkwɛstʃən bɪˈfɔr aɪv æskt wʌn/"},{"start":266.96,"end":269.2,"text":"That's something I remind myself of.","words":[["That's",266.96],["something",267.32],["I",267.68],["remind",267.76],["myself",268.16],["of.",268.6]],"ipa":"/ðæts ˈsʌmθɪŋ aɪ riˈmaɪnd ˌmaɪˈsɛlf ʌv/"},{"start":269.2,"end":271.4,"text":"A conversation gives you help.","words":[["A",269.2],["conversation",269.28],["gives",270.24],["you",270.52],["help.",270.68]],"ipa":"/ə ˌkɑnvərˈseɪʃən ɡɪvz ju hɛlp/"},{"start":271.4,"end":275.16,"text":"The other person can guide you toward the part they're curious about.","words":[["The",271.4],["other",271.6],["person",271.8],["can",272.2],["guide",272.4],["you",272.76],["toward",272.88],["the",273.24],["part",273.36],["they're",273.6],["curious",273.76],["about.",274.2]],"ipa":"/ðə ˈʌðər ˈpɝsən kæn ɡaɪd ju təˈwɔrd ðə pɑrt ðɛr ˈkjʊriəs əˈbaʊt/"},{"start":275.16,"end":277.48,"text":"Which takes some pressure off your English, too.","words":[["Which",275.16],["takes",275.48],["some",275.72],["pressure",275.88],["off",276.28],["your",276.44],["English,",276.56],["too.",276.92]],"ipa":"/wɪtʃ teɪks sʌm ˈprɛʃər ɔf jɔr ˈɪŋɡlɪʃ tu/"},{"start":277.48,"end":280.96,"text":"You're sharing a moment, and you can build the story together.","words":[["You're",277.48],["sharing",277.68],["a",278.08],["moment,",278.16],["and",278.68],["you",278.84],["can",278.92],["build",279.12],["the",279.4],["story",279.48],["together.",279.84]],"ipa":"/jʊr ˈʃɛrɪŋ ə ˈmoʊmənt ənd ju kæn bɪld ðə ˈstɔri təˈɡɛðər/"},{"start":280.96,"end":283.6,"text":"But, I'm curious about something you said earlier.","words":[["But,",280.96],["I'm",281.36],["curious",281.52],["about",281.92],["something",282.12],["you",282.48],["said",282.6],["earlier.",282.84]],"ipa":"/bʌt aɪm ˈkjʊriəs əˈbaʊt ˈsʌmθɪŋ ju sɛd ˈɝliər/"},{"start":283.6,"end":285.88,"text":"You said your day was better now.","words":[["You",283.6],["said",283.76],["your",284.04],["day",284.2],["was",284.52],["better",284.76],["now.",285.04]],"ipa":"/ju sɛd jɔr deɪ wɑz ˈbɛtər naʊ/"},{"start":285.88,"end":287.72,"text":"What actually turned it around?","words":[["What",285.88],["actually",286.08],["turned",286.44],["it",286.72],["around?",286.8]],"ipa":"/wʌt ˈækˌtʃuəli tɝnd ɪt ərˈaʊnd/"},{"start":287.72,"end":291.6,"text":"A student stayed after class to tell me she used something we practiced.","words":[["A",287.72],["student",287.8],["stayed",288.28],["after",288.56],["class",288.84],["to",289.24],["tell",289.36],["me",289.56],["she",289.72],["used",289.92],["something",290.32],["we",290.6],["practiced.",290.72]],"ipa":"/ə ˈstudənt steɪd ˈæftər klæs tu tɛl mi ʃi juzd ˈsʌmθɪŋ wi ˈpræktəst/"},{"start":291.6,"end":296.44,"text":"She'd asked a coworker about his weekend, and they ended up talking for 10 minutes.","words":[["She'd",291.6],["asked",291.92],["a",292.2],["coworker",292.28],["about",292.8],["his",293],["weekend,",293.16],["and",293.72],["they",293.88],["ended",294.04],["up",294.32],["talking",294.44],["for",294.88],["10",295.04],["minutes.",295.28]],"ipa":"/ʃid æskt ə ˈkoʊˈwɝkər əˈbaʊt hɪz ˈwiˌkɛnd ənd ðeɪ ˈɛndəd ʌp ˈtɔkɪŋ fɔr ˈmɪnəts/"},{"start":296.44,"end":298.2,"text":"Oh, that must have felt good.","words":[["Oh,",296.44],["that",296.8],["must",296.96],["have",297.12],["felt",297.24],["good.",297.52]],"ipa":"/oʊ ðæt mʌst hæv fɛlt ɡʊd/"},{"start":298.2,"end":302.4,"text":"Was she usually nervous about starting conversations at work? Very.","words":[["Was",298.2],["she",298.36],["usually",298.52],["nervous",298.96],["about",299.36],["starting",299.6],["conversations",299.96],["at",300.68],["work?",300.76],["Very.",301.56]],"ipa":"/wɑz ʃi ˈjuʒəwəli ˈnɝvəs əˈbaʊt ˈstɑrtɪŋ ˌkɑnvərˈseɪʃənz æt wɝk ˈvɛri/"},{"start":302.4,"end":306.64,"text":"She'd been eating lunch at her desk because joining the others felt uncomfortable.","words":[["She'd",302.4],["been",302.64],["eating",302.88],["lunch",303.2],["at",303.44],["her",303.52],["desk",303.64],["because",304.08],["joining",304.48],["the",304.84],["others",304.96],["felt",305.32],["uncomfortable.",305.64]],"ipa":"/ʃid bɪn ˈitɪŋ lʌntʃ æt hɝ dɛsk bɪˈkɔz ˈdʒɔɪnɪŋ ðə ˈʌðərz fɛlt ənˈkʌmfərtəbəl/"},{"start":306.64,"end":308.4,"text":"Today, she sat with them.","words":[["Today,",306.64],["she",307.16],["sat",307.4],["with",307.64],["them.",307.8]],"ipa":"/təˈdeɪ ʃi sæt wɪð ðɛm/"},{"start":308.4,"end":311.6,"text":"That mattered more to me than arriving a little late.","words":[["That",308.4],["mattered",308.68],["more",309.08],["to",309.32],["me",309.48],["than",309.68],["arriving",309.92],["a",310.4],["little",310.44],["late.",310.72]],"ipa":"/ðæt ˈmætərd mɔr tu mi ðæn ərˈaɪvɪŋ ə ˈlɪtəl leɪt/"},{"start":311.6,"end":312.92,"text":"I can see why.","words":[["I",311.6],["can",311.72],["see",311.88],["why.",312.04]],"ipa":"/aɪ kæn si waɪ/"},{"start":312.92,"end":318.08,"text":"And I noticed you didn't just tell me what happened, you told me why it changed your mood.","words":[["And",312.92],["I",313.08],["noticed",313.12],["you",313.52],["didn't",313.64],["just",313.88],["tell",314.12],["me",314.36],["what",314.48],["happened,",314.72],["you",315.48],["told",315.64],["me",315.92],["why",316.08],["it",316.4],["changed",316.52],["your",316.96],["mood.",317.12]],"ipa":"/ənd aɪ ˈnoʊtəst ju ˈdɪdənt dʒʌst tɛl mi wʌt ˈhæpənd ju toʊld mi waɪ ɪt tʃeɪndʒd jɔr mud/"},{"start":318.08,"end":320.12,"text":"Your question helped me get there.","words":[["Your",318.08],["question",318.28],["helped",318.8],["me",319.08],["get",319.2],["there.",319.4]],"ipa":"/jɔr ˈkwɛstʃən hɛlpt mi ɡɛt ðɛr/"},{"start":320.12,"end":321.36,"text":"\\"What turned it around?\\"","words":[["\\"What",320.12],["turned",320.4],["it",320.64],["around?\\"",320.72]],"ipa":"/wʌt tɝnd ɪt ərˈaʊnd/"},{"start":321.36,"end":324.32,"text":"felt more inviting than \\"What else did you do?\\"","words":[["felt",321.36],["more",321.64],["inviting",321.8],["than",322.44],["\\"What",322.84],["else",323.04],["did",323.24],["you",323.4],["do?\\"",323.48]],"ipa":"/fɛlt mɔr ˌɪnˈvaɪtɪŋ ðæn wʌt ɛls dɪd ju du/"},{"start":324.32,"end":328.72,"text":"Although I've definitely asked what else when my brain couldn't think of anything better.","words":[["Although",324.32],["I've",324.68],["definitely",324.88],["asked",325.4],["what",325.76],["else",326.08],["when",326.4],["my",326.52],["brain",326.68],["couldn't",327.08],["think",327.36],["of",327.56],["anything",327.64],["better.",328]],"ipa":"/ˌɔlˈðoʊ aɪv ˈdɛfənətli æskt wʌt ɛls wɛn maɪ breɪn ˈkʊdənt θɪŋk ʌv ˈɛniˌθɪŋ ˈbɛtər/"},{"start":328.72,"end":332.28,"text":"Sometimes I'm interested, but I sound like I'm checking boxes.","words":[["Sometimes",328.72],["I'm",329.2],["interested,",329.32],["but",330.04],["I",330.2],["sound",330.28],["like",330.68],["I'm",330.84],["checking",330.92],["boxes.",331.24]],"ipa":"/səmˈtaɪmz aɪm ˈɪntrəstɪd bʌt aɪ saʊnd laɪk aɪm ˈtʃɛkɪŋ ˈbɑksəz/"},{"start":332.28,"end":335.12,"text":"Then pick up one detail they've already given you.","words":[["Then",332.28],["pick",332.64],["up",332.84],["one",333.04],["detail",333.28],["they've",333.72],["already",333.96],["given",334.24],["you.",334.6]],"ipa":"/ðɛn pɪk ʌp wʌn dɪˈteɪl ðeɪv ɔlˈrɛdi ˈɡɪvən ju/"},{"start":335.12,"end":340.48,"text":"If someone says lunch with a coworker was awkward, I'd ask, \\"Oh, what made it awkward?\\"","words":[["If",335.12],["someone",335.28],["says",335.6],["lunch",335.96],["with",336.28],["a",336.4],["coworker",336.44],["was",337],["awkward,",337.24],["I'd",338],["ask,",338.2],["\\"Oh,",338.72],["what",339.12],["made",339.28],["it",339.44],["awkward?\\"",339.56]],"ipa":"/ɪf ˈsʌmˌwʌn sɛz lʌntʃ wɪð ə ˈkoʊˈwɝkər wɑz ˈɑkwərd aɪd æsk oʊ wʌt meɪd ɪt ˈɑkwərd/"},{"start":340.48,"end":342.64,"text":"Would you always ask that directly?","words":[["Would",340.48],["you",340.68],["always",340.8],["ask",341.12],["that",341.44],["directly?",341.68]],"ipa":"/wʊd ju ˈɔlˌweɪz æsk ðæt dərˈɛktli/"},{"start":342.64,"end":346.92,"text":"They might not want to explain a personal problem with someone at work. Good point.","words":[["They",342.64],["might",342.76],["not",342.96],["want",343.16],["to",343.36],["explain",343.44],["a",343.88],["personal",343.96],["problem",344.36],["with",344.72],["someone",344.88],["at",345.16],["work.",345.24],["Good",346.12],["point.",346.4]],"ipa":"/ðeɪ maɪt nɑt wɑnt tu ɪkˈspleɪn ə ˈpɝsɪnəl ˈprɑbləm wɪð ˈsʌmˌwʌn æt wɝk ɡʊd pɔɪnt/"},{"start":346.92,"end":348.48,"text":"I could leave more room.","words":[["I",346.92],["could",347.04],["leave",347.24],["more",347.48],["room.",347.68]],"ipa":"/aɪ kʊd liv mɔr rum/"},{"start":348.48,"end":349.92,"text":"Was it one of those days?","words":[["Was",348.48],["it",348.68],["one",348.84],["of",349],["those",349.08],["days?",349.32]],"ipa":"/wɑz ɪt wʌn ʌv ðoʊz deɪz/"},{"start":349.92,"end":351.2,"text":"Gives them a choice.","words":[["Gives",349.92],["them",350.2],["a",350.32],["choice.",350.4]],"ipa":"/ɡɪvz ðɛm ə tʃɔɪs/"},{"start":351.2,"end":354.2,"text":"They can laugh and move on or tell me more.","words":[["They",351.2],["can",351.32],["laugh",351.56],["and",351.88],["move",352],["on",352.2],["or",352.64],["tell",352.96],["me",353.2],["more.",353.36]],"ipa":"/ðeɪ kæn læf ənd muv ɑn ɔr tɛl mi mɔr/"},{"start":354.2,"end":355.68,"text":"That feels gentler.","words":[["That",354.2],["feels",354.44],["gentler.",354.72]],"ipa":"/ðæt filz ˈdʒɛntlər/"},{"start":355.68,"end":359,"text":"I had dinner with a friend recently and he said work had been rough.","words":[["I",355.68],["had",355.8],["dinner",356],["with",356.24],["a",356.36],["friend",356.44],["recently",356.76],["and",357.2],["he",357.32],["said",357.44],["work",357.72],["had",357.96],["been",358.08],["rough.",358.24]],"ipa":"/aɪ hæd ˈdɪnər wɪð ə frɛnd ˈrisəntli ənd hi sɛd wɝk hæd bɪn rʌf/"},{"start":359,"end":362.92,"text":"I almost asked five questions before he'd even taken a bite.","words":[["I",359],["almost",359.12],["asked",359.48],["five",359.72],["questions",360.04],["before",360.56],["he'd",360.88],["even",361.04],["taken",361.2],["a",361.52],["bite.",361.56]],"ipa":"/aɪ ˈɔlˌmoʊst æskt faɪv ˈkwɛstʃənz bɪˈfɔr hid ˈivɪn ˈteɪkən ə baɪt/"},{"start":362.92,"end":364.76,"text":"Let the man have his dinner.","words":[["Let",362.92],["the",363.24],["man",363.32],["have",363.6],["his",363.8],["dinner.",363.96]],"ipa":"/lɛt ðə mæn hæv hɪz ˈdɪnər/"},{"start":364.76,"end":366.32,"text":"What did you end up saying?","words":[["What",364.76],["did",364.88],["you",365.04],["end",365.12],["up",365.28],["saying?",365.4]],"ipa":"/wʌt dɪd ju ɛnd ʌp ˈseɪɪŋ/"},{"start":366.32,"end":368.12,"text":"Sounds like you've had a lot going on.","words":[["Sounds",366.32],["like",366.64],["you've",366.8],["had",366.92],["a",367.04],["lot",367.08],["going",367.28],["on.",367.56]],"ipa":"/saʊndz laɪk juv hæd ə lɑt ˈɡoʊɪŋ ɑn/"},{"start":368.12,"end":372.36,"text":"He nodded, ate some pasta, and then started telling me about a difficult meeting.","words":[["He",368.12],["nodded,",368.28],["ate",368.96],["some",369.12],["pasta,",369.28],["and",369.84],["then",369.96],["started",370.12],["telling",370.44],["me",370.72],["about",370.8],["a",371],["difficult",371.08],["meeting.",371.52]],"ipa":"/hi ˈnɑdəd eɪt sʌm ˈpɑstə ənd ðɛn ˈstɑrtɪd ˈtɛlɪŋ mi əˈbaʊt ə ˈdɪfəkəlt ˈmitɪŋ/"},{"start":372.36,"end":374.6,"text":"So, you gave him a little space.","words":[["So,",372.36],["you",372.76],["gave",372.92],["him",373.2],["a",373.4],["little",373.44],["space.",373.72]],"ipa":"/soʊ ju ɡeɪv hɪm ə ˈlɪtəl speɪs/"},{"start":374.6,"end":377.32,"text":"That's easy to forget when you're practicing English.","words":[["That's",374.6],["easy",375],["to",375.28],["forget",375.4],["when",375.8],["you're",375.96],["practicing",376.08],["English.",376.56]],"ipa":"/ðæts ˈizi tu fərˈɡɛt wɛn jʊr ˈpræktəsɪŋ ˈɪŋɡlɪʃ/"},{"start":377.32,"end":381.76,"text":"You can get so focused on your next question that you miss their response.","words":[["You",377.32],["can",377.44],["get",377.6],["so",377.8],["focused",378.04],["on",378.56],["your",378.68],["next",378.8],["question",379.12],["that",379.68],["you",379.92],["miss",380.04],["their",380.32],["response.",380.52]],"ipa":"/ju kæn ɡɛt soʊ ˈfoʊkəst ɑn jɔr nɛkst ˈkwɛstʃən ðæt ju mɪs ðɛr rɪˈspɑns/"},{"start":381.76,"end":384.48,"text":"Especially if you've prepared a question in your head.","words":[["Especially",381.76],["if",382.24],["you've",382.4],["prepared",382.56],["a",383.04],["question",383.08],["in",383.56],["your",383.64],["head.",383.8]],"ipa":"/əˈspɛʃli ɪf juv priˈpɛrd ə ˈkwɛstʃən ɪn jɔr hɛd/"},{"start":384.48,"end":389,"text":"They mention a terrible afternoon and you're ready with, \\"What did you have for breakfast?\\"","words":[["They",384.48],["mention",384.6],["a",385],["terrible",385.04],["afternoon",385.56],["and",386.24],["you're",386.4],["ready",386.56],["with,",386.84],["\\"What",387.24],["did",387.4],["you",387.52],["have",387.64],["for",387.8],["breakfast?\\"",387.92]],"ipa":"/ðeɪ ˈmɛnʃən ə ˈtɛrəbəl ˌæftərˈnun ənd jʊr ˈrɛdi wɪð wʌt dɪd ju hæv fɔr ˈbrɛkfəst/"},{"start":389,"end":391.88,"text":"That would be quite a change of direction.","words":[["That",389],["would",389.4],["be",389.56],["quite",389.84],["a",390.2],["change",390.28],["of",390.6],["direction.",390.68]],"ipa":"/ðæt wʊd bi kwaɪt ə tʃeɪndʒ ʌv dərˈɛkʃən/"},{"start":391.88,"end":394.52,"text":"A simple reaction can help you stay with them.","words":[["A",391.88],["simple",392],["reaction",392.4],["can",392.96],["help",393.08],["you",393.28],["stay",393.4],["with",393.64],["them.",393.84]],"ipa":"/ə ˈsɪmpəl riˈækʃən kæn hɛlp ju steɪ wɪð ðɛm/"},{"start":394.52,"end":396.44,"text":"\\"Oh, that sounds frustrating.\\"","words":[["\\"Oh,",394.52],["that",394.88],["sounds",395.2],["frustrating.\\"",395.56]],"ipa":"/oʊ ðæt saʊndz ˈfrʌˌstreɪtɪŋ/"},{"start":396.44,"end":398.64,"text":"Then see whether they keep talking.","words":[["Then",396.44],["see",396.8],["whether",397.04],["they",397.28],["keep",397.44],["talking.",397.68]],"ipa":"/ðɛn si ˈwɛðər ðeɪ kip ˈtɔkɪŋ/"},{"start":398.64,"end":400.76,"text":"And the reaction needs to fit.","words":[["And",398.64],["the",398.84],["reaction",398.92],["needs",399.48],["to",399.8],["fit.",399.96]],"ipa":"/ənd ðə riˈækʃən nidz tu fɪt/"},{"start":400.76,"end":406.32,"text":"If someone says they finally got a quiet evening, \\"That's a shame\\" probably isn't what you want.","words":[["If",400.76],["someone",400.92],["says",401.24],["they",401.52],["finally",401.68],["got",402.16],["a",402.32],["quiet",402.36],["evening,",402.76],["\\"That's",403.52],["a",403.84],["shame\\"",403.88],["probably",404.44],["isn't",405],["what",405.24],["you",405.4],["want.",405.52]],"ipa":"/ɪf ˈsʌmˌwʌn sɛz ðeɪ ˈfaɪnəli ɡɑt ə ˈkwaɪət ˈivnɪŋ ðæts ə ʃeɪm ˈprɑbəˌbli ˈɪzənt wʌt ju wɑnt/"},{"start":406.32,"end":410.72,"text":"Unless they hate quiet evenings, which you might discover by listening.","words":[["Unless",406.32],["they",406.92],["hate",407.12],["quiet",407.44],["evenings,",407.8],["which",408.56],["you",408.84],["might",408.96],["discover",409.2],["by",409.64],["listening.",409.8]],"ipa":"/ənˈlɛs ðeɪ heɪt ˈkwaɪət ˈivnɪŋz wɪtʃ ju maɪt dɪˈskʌvər baɪ ˈlɪsənɪŋ/"},{"start":410.72,"end":412.92,"text":"I'd probably say, \\"That sounds nice.","words":[["I'd",410.72],["probably",410.92],["say,",411.4],["\\"That",411.92],["sounds",412.16],["nice.",412.44]],"ipa":"/aɪd ˈprɑbəˌbli seɪ ðæt saʊndz naɪs/"},{"start":412.92,"end":414.56,"text":"Did you get to relax?\\"","words":[["Did",412.92],["you",413.16],["get",413.24],["to",413.4],["relax?\\"",413.48]],"ipa":"/dɪd ju ɡɛt tu rɪˈlæks/"},{"start":414.56,"end":419.8,"text":"Now, if you're listening and thinking of a conversation you'd like to have, tell us in the comments who it's with.","words":[["Now,",414.56],["if",414.88],["you're",415.08],["listening",415.2],["and",415.64],["thinking",415.76],["of",416.08],["a",416.2],["conversation",416.24],["you'd",416.96],["like",417.16],["to",417.36],["have,",417.48],["tell",417.88],["us",418.08],["in",418.2],["the",418.28],["comments",418.36],["who",418.8],["it's",418.96],["with.",419.12]],"ipa":"/naʊ ɪf jʊr ˈlɪsənɪŋ ənd ˈθɪŋkɪŋ ʌv ə ˌkɑnvərˈseɪʃən jud laɪk tu hæv tɛl ʌs ɪn ðə ˈkɑmɛnts hu ɪts wɪð/"},{"start":419.8,"end":422.52,"text":"A co-worker, a friend, someone at home.","words":[["A",419.8],["co-worker,",419.88],["a",420.64],["friend,",420.68],["someone",421.28],["at",421.6],["home.",421.68]],"ipa":"/ə ˈkoʊˈwɝkər ə frɛnd ˈsʌmˌwʌn æt hoʊm/"},{"start":422.52,"end":423.68,"text":"I'd love to know.","words":[["I'd",422.52],["love",422.76],["to",423],["know.",423.12]],"ipa":"/aɪd lʌv tu noʊ/"},{"start":423.68,"end":428.92,"text":"And if these conversations help you, give the video a like and subscribe to Mr. English Channel.","words":[["And",423.68],["if",423.92],["these",424.08],["conversations",424.28],["help",425.08],["you,",425.32],["give",425.68],["the",425.88],["video",425.96],["a",426.28],["like",426.36],["and",426.76],["subscribe",426.92],["to",427.48],["Mr.",427.56],["English",427.88],["Channel.",428.24]],"ipa":"/ənd ɪf ðiz ˌkɑnvərˈseɪʃənz hɛlp ju ɡɪv ðə ˈvɪdioʊ ə laɪk ənd səbˈskraɪb tu ˈmɪstər ˈɪŋɡlɪʃ ˈtʃænəl/"},{"start":428.92,"end":432.28,"text":"You can bring a few of these expressions into your next chat.","words":[["You",428.92],["can",429.08],["bring",429.24],["a",429.44],["few",429.52],["of",429.8],["these",429.88],["expressions",430.08],["into",430.76],["your",431],["next",431.12],["chat.",431.36]],"ipa":"/ju kæn brɪŋ ə fju ʌv ðiz ɪkˈsprɛʃənz ˈɪntu jɔr nɛkst tʃæt/"},{"start":432.28,"end":437.08,"text":"Speaking of those chats, what happens when the answer is honestly pretty negative?","words":[["Speaking",432.28],["of",432.76],["those",432.88],["chats,",433.08],["what",433.92],["happens",434.08],["when",434.44],["the",434.56],["answer",434.72],["is",435.12],["honestly",435.44],["pretty",435.88],["negative?",436.28]],"ipa":"/ˈspikɪŋ ʌv ðoʊz tʃæts wʌt ˈhæpənz wɛn ðə ˈænsər ɪz ˈɑnəstli ˈprɪti ˈnɛɡətɪv/"},{"start":437.08,"end":441.08,"text":"Sometimes someone asks about my day and I don't want to pretend it was fine.","words":[["Sometimes",437.08],["someone",437.6],["asks",437.92],["about",438.2],["my",438.44],["day",438.6],["and",439],["I",439.2],["don't",439.24],["want",439.52],["to",439.68],["pretend",439.72],["it",440.12],["was",440.24],["fine.",440.4]],"ipa":"/səmˈtaɪmz ˈsʌmˌwʌn æsks əˈbaʊt maɪ deɪ ənd aɪ doʊnt wɑnt tu priˈtɛnd ɪt wɑz faɪn/"},{"start":441.08,"end":442.4,"text":"You don't have to.","words":[["You",441.08],["don't",441.24],["have",441.52],["to.",441.8]],"ipa":"/ju doʊnt hæv tu/"},{"start":442.4,"end":445.84,"text":"You could say, \\"Honestly, it's been a rough one.","words":[["You",442.4],["could",442.6],["say,",442.88],["\\"Honestly,",443.76],["it's",444.44],["been",444.8],["a",444.96],["rough",445.04],["one.",445.28]],"ipa":"/ju kʊd seɪ ˈɑnəstli ɪts bɪn ə rʌf wʌn/"},{"start":445.84,"end":448.12,"text":"A couple of things went wrong at work.\\"","words":[["A",445.84],["couple",445.96],["of",446.32],["things",446.44],["went",446.8],["wrong",447],["at",447.24],["work.\\"",447.36]],"ipa":"/ə ˈkʌpəl ʌv θɪŋz wɛnt rɔŋ æt wɝk/"},{"start":448.12,"end":451.56,"text":"That's honest without sharing everything immediately.","words":[["That's",448.12],["honest",448.6],["without",449.16],["sharing",449.56],["everything",450],["immediately.",450.64]],"ipa":"/ðæts ˈɑnəst wɪˈθaʊt ˈʃɛrɪŋ ˈɛvriˌθɪŋ ˌɪˈmiˌdiətli/"},{"start":451.56,"end":453.16,"text":"I like a rough one.","words":[["I",451.56],["like",451.6],["a",451.96],["rough",452.08],["one.",452.48]],"ipa":"/aɪ laɪk ə rʌf wʌn/"},{"start":453.16,"end":458.4,"text":"It sounds natural, but it doesn't tell the other person whether I need help or just need to complain for a minute.","words":[["It",453.16],["sounds",453.28],["natural,",453.56],["but",454.04],["it",454.32],["doesn't",454.44],["tell",454.76],["the",454.88],["other",455],["person",455.16],["whether",455.56],["I",455.84],["need",455.92],["help",456.16],["or",456.56],["just",456.72],["need",456.96],["to",457.16],["complain",457.24],["for",457.64],["a",457.8],["minute.",457.84]],"ipa":"/ɪt saʊndz ˈnætʃərəl bʌt ɪt ˈdʌzənt tɛl ðə ˈʌðər ˈpɝsən ˈwɛðər aɪ nid hɛlp ɔr dʒʌst nid tu kəmˈpleɪn fɔr ə ˈmɪnət/"},{"start":458.4,"end":460.24,"text":"Then you can tell them.","words":[["Then",458.4],["you",458.92],["can",459.16],["tell",459.32],["them.",459.56]],"ipa":"/ðɛn ju kæn tɛl ðɛm/"},{"start":460.24,"end":463.4,"text":"I sometimes say, \\"Can I vent for a minute?\\"","words":[["I",460.24],["sometimes",460.36],["say,",460.92],["\\"Can",461.68],["I",461.88],["vent",462],["for",462.36],["a",462.6],["minute?\\"",462.64]],"ipa":"/aɪ səmˈtaɪmz seɪ kæn aɪ vɛnt fɔr ə ˈmɪnət/"},{"start":463.4,"end":467.08,"text":"With a friend, that means I want to talk about what's bothering me.","words":[["With",463.4],["a",463.6],["friend,",463.64],["that",464.16],["means",464.4],["I",464.8],["want",464.92],["to",465.2],["talk",465.32],["about",465.6],["what's",465.88],["bothering",466.12],["me.",466.64]],"ipa":"/wɪð ə frɛnd ðæt minz aɪ wɑnt tu tɔk əˈbaʊt wʌts ˈbɑðərɪŋ mi/"},{"start":467.08,"end":470.72,"text":"Would you be okay if they said, \\"Can we talk after dinner?\\"","words":[["Would",467.08],["you",467.4],["be",467.52],["okay",467.72],["if",468],["they",468.16],["said,",468.32],["\\"Can",468.8],["we",469.04],["talk",469.16],["after",469.56],["dinner?\\"",469.92]],"ipa":"/wʊd ju bi ˌoʊˈkeɪ ɪf ðeɪ sɛd kæn wi tɔk ˈæftər ˈdɪnər/"},{"start":470.72,"end":473.52,"text":"Because asking might mean they don't have the energy right then.","words":[["Because",470.72],["asking",471.08],["might",471.48],["mean",471.72],["they",471.88],["don't",472],["have",472.28],["the",472.4],["energy",472.52],["right",472.84],["then.",473.08]],"ipa":"/bɪˈkɔz ˈæskɪŋ maɪt min ðeɪ doʊnt hæv ðə ˈɛnərdʒi raɪt ðɛn/"},{"start":473.52,"end":476.64,"text":"Yes, though I might feel disappointed.","words":[["Yes,",473.52],["though",474.4],["I",474.8],["might",474.96],["feel",475.28],["disappointed.",475.48]],"ipa":"/jɛs ðoʊ aɪ maɪt fil ˌdɪsəˈpɔɪntɪd/"},{"start":476.64,"end":484,"text":"I'd rather have their attention later than tell the whole story while they're trying to handle three other things. That's fair.","words":[["I'd",476.64],["rather",476.84],["have",477.12],["their",477.36],["attention",477.52],["later",478.04],["than",478.56],["tell",478.76],["the",478.96],["whole",479.12],["story",479.48],["while",480.12],["they're",480.32],["trying",480.48],["to",480.92],["handle",481.04],["three",481.44],["other",481.76],["things.",482],["That's",482.8],["fair.",483.08]],"ipa":"/aɪd ˈræðər hæv ðɛr əˈtɛnʃən ˈleɪtər ðæn tɛl ðə hoʊl ˈstɔri waɪl ðɛr ˈtraɪɪŋ tu ˈhændəl θri ˈʌðər θɪŋz ðæts fɛr/"},{"start":484,"end":487.28,"text":"I've been the person trying to listen while answering a message.","words":[["I've",484],["been",484.2],["the",484.44],["person",484.52],["trying",484.84],["to",485.16],["listen",485.28],["while",485.72],["answering",486],["a",486.4],["message.",486.44]],"ipa":"/aɪv bɪn ðə ˈpɝsən ˈtraɪɪŋ tu ˈlɪsən waɪl ˈænsərɪŋ ə ˈmɛsədʒ/"},{"start":487.28,"end":489.92,"text":"Then I ask a question they've already answered.","words":[["Then",487.28],["I",487.56],["ask",487.68],["a",487.92],["question",488],["they've",488.44],["already",488.72],["answered.",489.08]],"ipa":"/ðɛn aɪ æsk ə ˈkwɛstʃən ðeɪv ɔlˈrɛdi ˈænsərd/"},{"start":489.92,"end":492.48,"text":"Nobody feels particularly loved in that moment.","words":[["Nobody",489.92],["feels",490.32],["particularly",490.6],["loved",491.32],["in",491.68],["that",491.76],["moment.",491.92]],"ipa":"/ˈnoʊˌbɑˌdi filz ˌpɑrˈtɪkjələrli lʌvd ɪn ðæt ˈmoʊmənt/"},{"start":492.48,"end":494.84,"text":"I've caught myself doing that, too.","words":[["I've",492.48],["caught",492.84],["myself",493.08],["doing",493.6],["that,",493.88],["too.",494.12]],"ipa":"/aɪv kɑt ˌmaɪˈsɛlf ˈduɪŋ ðæt tu/"},{"start":494.84,"end":500.28,"text":"Putting my phone down helps, but once I'm listening, I've got another habit to watch,","words":[["Putting",494.84],["my",495.16],["phone",495.32],["down",495.64],["helps,",495.96],["but",496.84],["once",497.08],["I'm",497.32],["listening,",497.52],["I've",498.16],["got",498.36],["another",498.6],["habit",499.08],["to",499.44],["watch,",499.56]],"ipa":"/ˈpʌtɪŋ maɪ foʊn daʊn hɛlps bʌt wʌns aɪm ˈlɪsənɪŋ aɪv ɡɑt əˈnʌðər ˈhæbət tu wɑtʃ/"},{"start":500.28,"end":503.72,"text":"offering a solution too quickly. Same here.","words":[["offering",500.28],["a",500.84],["solution",500.92],["too",501.76],["quickly.",501.96],["Same",502.68],["here.",503.08]],"ipa":"/ˈɔfərɪŋ ə səˈluʃən tu ˈkwɪkli seɪm hir/"},{"start":503.72,"end":506.64,"text":"Someone says, \\"My manager changed the plan again.\\"","words":[["Someone",503.72],["says,",504.12],["\\"My",504.6],["manager",504.8],["changed",505.28],["the",505.64],["plan",505.72],["again.\\"",506.04]],"ipa":"/ˈsʌmˌwʌn sɛz maɪ ˈmænədʒər tʃeɪndʒd ðə plæn əˈɡɛn/"},{"start":506.64,"end":509.88,"text":"And I'm already preparing a speech they should deliver tomorrow morning.","words":[["And",506.64],["I'm",506.92],["already",507.12],["preparing",507.44],["a",507.88],["speech",507.92],["they",508.36],["should",508.48],["deliver",508.68],["tomorrow",509],["morning.",509.32]],"ipa":"/ənd aɪm ɔlˈrɛdi priˈpɛrɪŋ ə spitʃ ðeɪ ʃʊd dɪˈlɪvər təˈmɑˌroʊ ˈmɔrnɪŋ/"},{"start":509.88,"end":514.08,"text":"Meanwhile, they're thinking, \\"Please don't give me another task.\\"","words":[["Meanwhile,",509.88],["they're",510.64],["thinking,",510.88],["\\"Please",511.68],["don't",512],["give",512.24],["me",512.4],["another",512.56],["task.\\"",513.12]],"ipa":"/ˈminˌwaɪl ðɛr ˈθɪŋkɪŋ pliz doʊnt ɡɪv mi əˈnʌðər tæsk/"},{"start":514.08,"end":518,"text":"Sometimes they just want you to understand why they're exhausted.","words":[["Sometimes",514.08],["they",514.68],["just",514.84],["want",515.2],["you",515.44],["to",515.56],["understand",515.68],["why",516.6],["they're",516.88],["exhausted.",517.08]],"ipa":"/səmˈtaɪmz ðeɪ dʒʌst wɑnt ju tu ˌʌndərˈstænd waɪ ðɛr ɪɡˈzɔstɪd/"},{"start":518,"end":519.68,"text":"So, how would you check?","words":[["So,",518],["how",518.36],["would",518.56],["you",518.72],["check?",518.84]],"ipa":"/soʊ haʊ wʊd ju tʃɛk/"},{"start":519.68,"end":520.68,"text":"\\"Do you want advice?\\"","words":[["\\"Do",519.68],["you",519.84],["want",519.96],["advice?\\"",520.16]],"ipa":"/du ju wɑnt ædˈvaɪs/"},{"start":520.68,"end":523.52,"text":"can sound a little formal when you're sitting on the couch together.","words":[["can",520.68],["sound",520.88],["a",521.24],["little",521.28],["formal",521.56],["when",522.04],["you're",522.16],["sitting",522.28],["on",522.52],["the",522.64],["couch",522.68],["together.",523]],"ipa":"/kæn saʊnd ə ˈlɪtəl ˈfɔrməl wɛn jʊr ˈsɪtɪŋ ɑn ðə kaʊtʃ təˈɡɛðər/"},{"start":523.52,"end":526,"text":"I might say, \\"Want to talk it through?","words":[["I",523.52],["might",523.68],["say,",524.04],["\\"Want",524.88],["to",525.08],["talk",525.16],["it",525.4],["through?",525.52]],"ipa":"/aɪ maɪt seɪ wɑnt tu tɔk ɪt θru/"},{"start":526,"end":528.16,"text":"Or do you just need to get it out?\\"","words":[["Or",526],["do",526.28],["you",526.44],["just",526.56],["need",526.88],["to",527.12],["get",527.24],["it",527.4],["out?\\"",527.56]],"ipa":"/ɔr du ju dʒʌst nid tu ɡɛt ɪt aʊt/"},{"start":528.16,"end":531.48,"text":"That sounds more like something I'd actually say at home.","words":[["That",528.16],["sounds",528.4],["more",528.76],["like",529],["something",529.24],["I'd",529.72],["actually",530.04],["say",530.52],["at",530.76],["home.",530.92]],"ipa":"/ðæt saʊndz mɔr laɪk ˈsʌmθɪŋ aɪd ˈækˌtʃuəli seɪ æt hoʊm/"},{"start":531.48,"end":536.08,"text":"And if they want help, I'd ask what they've tried before suggesting anything.","words":[["And",531.48],["if",531.76],["they",531.92],["want",532.04],["help,",532.32],["I'd",532.76],["ask",533.04],["what",533.4],["they've",533.56],["tried",533.76],["before",534.12],["suggesting",534.56],["anything.",535.12]],"ipa":"/ənd ɪf ðeɪ wɑnt hɛlp aɪd æsk wʌt ðeɪv traɪd bɪˈfɔr səˈdʒɛstɪŋ ˈɛniˌθɪŋ/"},{"start":536.08,"end":538.84,"text":"They've probably thought about the situation longer than I have.","words":[["They've",536.08],["probably",536.24],["thought",536.64],["about",536.88],["the",537.08],["situation",537.16],["longer",537.76],["than",538.04],["I",538.2],["have.",538.32]],"ipa":"/ðeɪv ˈprɑbəˌbli θɔt əˈbaʊt ðə ˌsɪtʃuˈeɪʃən ˈlɔŋɡər ðæn aɪ hæv/"},{"start":538.84,"end":544.56,"text":"Definitely, though sometimes a difficult day needs something simpler first.","words":[["Definitely,",538.84],["though",540],["sometimes",540.4],["a",541.12],["difficult",541.2],["day",541.8],["needs",542.24],["something",542.6],["simpler",543.08],["first.",543.68]],"ipa":"/ˈdɛfənətli ðoʊ səmˈtaɪmz ə ˈdɪfəkəlt deɪ nidz ˈsʌmθɪŋ ˈsɪmpələr fɝst/"},{"start":544.56,"end":553.12,"text":"Yesterday, my sister called sounding completely worn out, and halfway through her story, I realized she hadn't eaten since breakfast.","words":[["Yesterday,",544.56],["my",545.28],["sister",545.48],["called",545.92],["sounding",546.36],["completely",546.76],["worn",547.52],["out,",547.8],["and",548.4],["halfway",548.6],["through",549],["her",549.2],["story,",549.36],["I",550.16],["realized",550.28],["she",551.04],["hadn't",551.24],["eaten",551.64],["since",551.96],["breakfast.",552.28]],"ipa":"/ˈjɛstərˌdeɪ maɪ ˈsɪstər kɔld ˈsaʊndɪŋ kəmˈplitli wɔrn aʊt ənd ˈhæfˈweɪ θru hɝ ˈstɔri aɪ ˈriəˌlaɪzd ʃi ˈhædənt ˈitən sɪns ˈbrɛkfəst/"},{"start":553.12,"end":555.64,"text":"Ugh, I've had that kind of afternoon.","words":[["Ugh,",553.12],["I've",553.68],["had",553.92],["that",554.12],["kind",554.28],["of",554.48],["afternoon.",554.56]],"ipa":"/ʌɡ aɪv hæd ðæt kaɪnd ʌv ˌæftərˈnun/"},{"start":555.64,"end":560.68,"text":"Did you point that out immediately, or did you find a slightly more diplomatic way to bring up lunch?","words":[["Did",555.64],["you",555.84],["point",555.92],["that",556.16],["out",556.32],["immediately,",556.48],["or",557.32],["did",557.6],["you",557.8],["find",557.92],["a",558.2],["slightly",558.28],["more",558.72],["diplomatic",558.96],["way",559.6],["to",559.72],["bring",559.84],["up",560],["lunch?",560.12]],"ipa":"/dɪd ju pɔɪnt ðæt aʊt ˌɪˈmiˌdiətli ɔr dɪd ju faɪnd ə ˈslaɪtli mɔr ˌdɪpləˈmætɪk weɪ tu brɪŋ ʌp lʌntʃ/"},{"start":560.68,"end":563.28,"text":"I asked, \\"Have you had a chance to eat?\\"","words":[["I",560.68],["asked,",560.84],["\\"Have",561.4],["you",561.64],["had",561.8],["a",561.96],["chance",562],["to",562.4],["eat?\\"",562.56]],"ipa":"/aɪ æskt hæv ju hæd ə tʃæns tu it/"},{"start":563.28,"end":567.44,"text":"She went quiet, then said, \\"Does the mint in my bag count?\\"","words":[["She",563.28],["went",563.48],["quiet,",563.72],["then",564.28],["said,",564.52],["\\"Does",565.24],["the",565.52],["mint",565.64],["in",565.96],["my",566.08],["bag",566.24],["count?\\"",566.68]],"ipa":"/ʃi wɛnt ˈkwaɪət ðɛn sɛd dʌz ðə mɪnt ɪn maɪ bæɡ kaʊnt/"},{"start":567.44,"end":573.68,"text":"So, we agreed that dinner might help before any big decisions. Probably wise.","words":[["So,",567.44],["we",567.8],["agreed",568],["that",568.48],["dinner",568.68],["might",568.96],["help",569.24],["before",569.56],["any",570],["big",570.24],["decisions.",570.52],["Probably",572.28],["wise.",572.76]],"ipa":"/soʊ wi əˈɡrid ðæt ˈdɪnər maɪt hɛlp bɪˈfɔr ˈɛni bɪɡ dɪˈsɪʒənz ˈprɑbəˌbli waɪz/"},{"start":573.68,"end":577.36,"text":"Did she feel better afterward, or was the day still a complete disaster?","words":[["Did",573.68],["she",573.92],["feel",574.08],["better",574.28],["afterward,",574.56],["or",575.08],["was",575.2],["the",575.44],["day",575.52],["still",575.76],["a",576.04],["complete",576.12],["disaster?",576.6]],"ipa":"/dɪd ʃi fil ˈbɛtər ˈæftərwərd ɔr wɑz ðə deɪ stɪl ə kəmˈplit dɪˈzæstər/"},{"start":577.36,"end":581.68,"text":"The problems were still there, but she sounded more like herself.","words":[["The",577.36],["problems",577.6],["were",578.16],["still",578.32],["there,",578.68],["but",579.44],["she",579.6],["sounded",579.8],["more",580.28],["like",580.52],["herself.",580.76]],"ipa":"/ðə ˈprɑbləmz wɝ stɪl ðɛr bʌt ʃi ˈsaʊndɪd mɔr laɪk hərˈsɛlf/"},{"start":581.68,"end":583.96,"text":"Then she told me something lovely.","words":[["Then",581.68],["she",582.04],["told",582.24],["me",582.52],["something",582.68],["lovely.",583.16]],"ipa":"/ðɛn ʃi toʊld mi ˈsʌmθɪŋ ˈlʌvli/"},{"start":583.96,"end":588.52,"text":"A woman on the bus had noticed her open backpack and helped her close it.","words":[["A",583.96],["woman",584.04],["on",584.44],["the",584.56],["bus",584.68],["had",585.08],["noticed",585.28],["her",585.76],["open",585.96],["backpack",586.24],["and",587.12],["helped",587.28],["her",587.6],["close",587.72],["it.",588.08]],"ipa":"/ə ˈwʊmən ɑn ðə bʌs hæd ˈnoʊtəst hɝ ˈoʊpən ˈbækˌpæk ənd hɛlpt hɝ kloʊs ɪt/"},{"start":588.52,"end":593.2,"text":"That's a nice little moment, especially on a day when you feel like everything's going wrong.","words":[["That's",588.52],["a",588.8],["nice",588.84],["little",589.08],["moment,",589.28],["especially",590.12],["on",590.64],["a",590.76],["day",590.8],["when",591],["you",591.16],["feel",591.24],["like",591.48],["everything's",591.72],["going",592.24],["wrong.",592.52]],"ipa":"/ðæts ə naɪs ˈlɪtəl ˈmoʊmənt əˈspɛʃli ɑn ə deɪ wɛn ju fil laɪk ˈɛvriˌθɪŋz ˈɡoʊɪŋ rɔŋ/"},{"start":593.2,"end":594.64,"text":"Someone was paying attention.","words":[["Someone",593.2],["was",593.6],["paying",593.76],["attention.",594]],"ipa":"/ˈsʌmˌwʌn wɑz ˈpeɪɪŋ əˈtɛnʃən/"},{"start":594.64,"end":596.84,"text":"She almost forgot to mention it.","words":[["She",594.64],["almost",594.92],["forgot",595.4],["to",595.84],["mention",595.92],["it.",596.28]],"ipa":"/ʃi ˈɔlˌmoʊst fərˈɡɑt tu ˈmɛnʃən ɪt/"},{"start":596.84,"end":604.44,"text":"I wonder how many small good things disappear from our stories because the frustrating parts take up so much room.","words":[["I",596.84],["wonder",596.96],["how",597.36],["many",597.6],["small",597.92],["good",598.44],["things",598.76],["disappear",599.24],["from",599.96],["our",600.2],["stories",600.32],["because",601.16],["the",601.48],["frustrating",601.6],["parts",602.32],["take",602.72],["up",603],["so",603.16],["much",603.48],["room.",603.8]],"ipa":"/aɪ ˈwʌndər haʊ ˈmɛni smɔl ɡʊd θɪŋz ˌdɪsəˈpɪr frʌm ˈaʊər ˈstɔriz bɪˈkɔz ðə ˈfrʌˌstreɪtɪŋ pɑrts teɪk ʌp soʊ mʌtʃ rum/"},{"start":604.44,"end":610.36,"text":"Quite a few probably, although I wouldn't want someone asking me to find the positive while I'm still upset.","words":[["Quite",604.44],["a",604.68],["few",604.72],["probably,",604.96],["although",606.08],["I",606.4],["wouldn't",606.52],["want",606.88],["someone",607.12],["asking",607.44],["me",607.8],["to",607.92],["find",608.04],["the",608.28],["positive",608.4],["while",608.92],["I'm",609.08],["still",609.2],["upset.",609.48]],"ipa":"/kwaɪt ə fju ˈprɑbəˌbli ˌɔlˈðoʊ aɪ ˈwʊdənt wɑnt ˈsʌmˌwʌn ˈæskɪŋ mi tu faɪnd ðə ˈpɑzətɪv waɪl aɪm stɪl əpˈsɛt/"},{"start":610.36,"end":613.92,"text":"Sometimes I need a minute with the bad part. Absolutely.","words":[["Sometimes",610.36],["I",610.88],["need",610.96],["a",611.24],["minute",611.28],["with",611.64],["the",611.76],["bad",611.88],["part.",612.12],["Absolutely.",612.68]],"ipa":"/səmˈtaɪmz aɪ nid ə ˈmɪnət wɪð ðə bæd pɑrt ˌæbsəˈlutli/"},{"start":613.92,"end":615.96,"text":"My sister brought it up herself.","words":[["My",613.92],["sister",614.08],["brought",614.52],["it",614.8],["up",614.92],["herself.",615.04]],"ipa":"/maɪ ˈsɪstər brɔt ɪt ʌp hərˈsɛlf/"},{"start":615.96,"end":622.48,"text":"I just asked whether anything had fallen out and suddenly we were talking about this stranger who'd helped her.","words":[["I",615.96],["just",616.12],["asked",616.44],["whether",616.92],["anything",617.24],["had",617.72],["fallen",617.92],["out",618.28],["and",618.88],["suddenly",619.08],["we",619.72],["were",619.88],["talking",620],["about",620.44],["this",620.76],["stranger",621],["who'd",621.56],["helped",621.76],["her.",622.04]],"ipa":"/aɪ dʒʌst æskt ˈwɛðər ˈɛniˌθɪŋ hæd ˈfɑlən aʊt ənd ˈsʌdənli wi wɝ ˈtɔkɪŋ əˈbaʊt ðɪs ˈstreɪndʒər hud hɛlpt hɝ/"},{"start":622.48,"end":624.48,"text":"There's something comforting about that.","words":[["There's",622.48],["something",622.68],["comforting",623],["about",623.4],["that.",623.68]],"ipa":"/ðɛrz ˈsʌmθɪŋ ˈkʌmfərtɪŋ əˈbaʊt ðæt/"},{"start":624.48,"end":628.24,"text":"The day can be difficult and still contain a moment you're glad happened.","words":[["The",624.48],["day",624.56],["can",624.76],["be",624.92],["difficult",625.04],["and",625.64],["still",625.8],["contain",626.12],["a",626.48],["moment",626.52],["you're",626.88],["glad",627],["happened.",627.36]],"ipa":"/ðə deɪ kæn bi ˈdɪfəkəlt ənd stɪl kənˈteɪn ə ˈmoʊmənt jʊr ɡlæd ˈhæpənd/"},{"start":628.24,"end":631.96,"text":"You don't have to choose one description for all of it. Exactly.","words":[["You",628.24],["don't",628.36],["have",628.52],["to",628.64],["choose",628.76],["one",629.24],["description",629.48],["for",630.08],["all",630.24],["of",630.44],["it.",630.52],["Exactly.",630.92]],"ipa":"/ju doʊnt hæv tu tʃuz wʌn dɪˈskrɪpʃən fɔr ɔl ʌv ɪt ɪɡˈzæktli/"},{"start":631.96,"end":636.04,"text":"And sharing that mix makes your conversation feel more real.","words":[["And",631.96],["sharing",632.12],["that",632.56],["mix",632.8],["makes",633.28],["your",633.52],["conversation",633.68],["feel",634.6],["more",634.92],["real.",635.24]],"ipa":"/ənd ˈʃɛrɪŋ ðæt mɪks meɪks jɔr ˌkɑnvərˈseɪʃən fil mɔr ril/"},{"start":636.04,"end":639.56,"text":"Work was stressful, but I had a really nice walk home.","words":[["Work",636.04],["was",636.44],["stressful,",636.64],["but",637.28],["I",637.48],["had",637.6],["a",637.8],["really",637.88],["nice",638.24],["walk",638.6],["home.",638.88]],"ipa":"/wɝk wɑz ˈstrɛsfəl bʌt aɪ hæd ə ˈrɪli naɪs wɔk hoʊm/"},{"start":639.56,"end":641.76,"text":"Both things belong in the story.","words":[["Both",639.56],["things",639.92],["belong",640.32],["in",640.8],["the",640.92],["story.",641]],"ipa":"/boʊθ θɪŋz bɪˈlɔŋ ɪn ðə ˈstɔri/"},{"start":641.76,"end":644.2,"text":"Can we try a short conversation with that?","words":[["Can",641.76],["we",641.92],["try",642.04],["a",642.28],["short",642.36],["conversation",642.72],["with",643.4],["that?",643.52]],"ipa":"/kæn wi traɪ ə ʃɔrt ˌkɑnvərˈseɪʃən wɪð ðæt/"},{"start":644.2,"end":648.56,"text":"I'll ask about your day and you give me an answer with a little of both. Sure.","words":[["I'll",644.2],["ask",644.4],["about",644.6],["your",644.84],["day",644.96],["and",645.36],["you",645.64],["give",645.76],["me",645.96],["an",646.04],["answer",646.24],["with",646.6],["a",646.8],["little",646.84],["of",647.12],["both.",647.24],["Sure.",647.88]],"ipa":"/aɪl æsk əˈbaʊt jɔr deɪ ənd ju ɡɪv mi æn ˈænsər wɪð ə ˈlɪtəl ʌv boʊθ ʃʊr/"},{"start":648.56,"end":653.12,"text":"Let's imagine we've just met outside a coffee shop after work. Go ahead.","words":[["Let's",648.56],["imagine",648.92],["we've",649.44],["just",649.72],["met",650.08],["outside",650.4],["a",650.88],["coffee",650.92],["shop",651.28],["after",651.64],["work.",651.92],["Go",652.48],["ahead.",652.6]],"ipa":"/lɛts ˌɪˈmædʒən wiv dʒʌst mɛt ˈaʊtˈsaɪd ə ˈkɑfi ʃɑp ˈæftər wɝk ɡoʊ əˈhɛd/"},{"start":653.12,"end":654.8,"text":"Hey, how'd your afternoon go?","words":[["Hey,",653.12],["how'd",653.48],["your",653.72],["afternoon",653.84],["go?",654.24]],"ipa":"/heɪ haʊd jɔr ˌæftərˈnun ɡoʊ/"},{"start":654.8,"end":657.72,"text":"You looked pretty busy when I saw you earlier. I was.","words":[["You",654.8],["looked",654.92],["pretty",655.16],["busy",655.32],["when",655.56],["I",655.72],["saw",655.76],["you",656],["earlier.",656.12],["I",656.72],["was.",656.84]],"ipa":"/ju lʊkt ˈprɪti ˈbɪzi wɛn aɪ sɔ ju ˈɝliər aɪ wɑz/"},{"start":657.72,"end":661.44,"text":"A meeting ran over, so I had to rush through the rest of my work,","words":[["A",657.72],["meeting",657.8],["ran",658.24],["over,",658.52],["so",658.92],["I",659.12],["had",659.24],["to",659.44],["rush",659.6],["through",659.92],["the",660.16],["rest",660.28],["of",660.52],["my",660.64],["work,",660.8]],"ipa":"/ə ˈmitɪŋ ræn ˈoʊvər soʊ aɪ hæd tu rʌʃ θru ðə rɛst ʌv maɪ wɝk/"},{"start":661.44,"end":665.28,"text":"but I managed to get outside for a few minutes afterward. Oh, good.","words":[["but",661.44],["I",661.72],["managed",661.8],["to",662.28],["get",662.4],["outside",662.56],["for",663.12],["a",663.24],["few",663.28],["minutes",663.52],["afterward.",663.84],["Oh,",664.64],["good.",664.76]],"ipa":"/bʌt aɪ ˈmænədʒd tu ɡɛt ˈaʊtˈsaɪd fɔr ə fju ˈmɪnəts ˈæftərwərd oʊ ɡʊd/"},{"start":665.28,"end":668.12,"text":"Did the break help or were you still thinking about the meeting?","words":[["Did",665.28],["the",665.44],["break",665.52],["help",665.76],["or",666.08],["were",666.2],["you",666.28],["still",666.4],["thinking",666.68],["about",666.96],["the",667.2],["meeting?",667.28]],"ipa":"/dɪd ðə breɪk hɛlp ɔr wɝ ju stɪl ˈθɪŋkɪŋ əˈbaʊt ðə ˈmitɪŋ/"},{"start":668.12,"end":670.56,"text":"At first I was still thinking about it.","words":[["At",668.12],["first",668.32],["I",668.84],["was",668.92],["still",669.08],["thinking",669.32],["about",669.76],["it.",670.08]],"ipa":"/æt fɝst aɪ wɑz stɪl ˈθɪŋkɪŋ əˈbaʊt ɪt/"},{"start":670.56,"end":674.16,"text":"Then I ran into an old neighbor and we ended up catching up.","words":[["Then",670.56],["I",671],["ran",671.12],["into",671.36],["an",671.6],["old",671.72],["neighbor",671.92],["and",672.44],["we",672.64],["ended",672.8],["up",673.04],["catching",673.2],["up.",673.6]],"ipa":"/ðɛn aɪ ræn ˈɪntu æn oʊld ˈneɪbər ənd wi ˈɛndəd ʌp ˈkætʃɪŋ ʌp/"},{"start":674.16,"end":676.32,"text":"I hadn't seen her in months.","words":[["I",674.16],["hadn't",674.28],["seen",674.64],["her",674.84],["in",675.04],["months.",675.24]],"ipa":"/aɪ ˈhædənt sin hɝ ɪn mʌnθs/"},{"start":676.32,"end":678,"text":"That must have been a nice surprise.","words":[["That",676.32],["must",676.48],["have",676.68],["been",676.76],["a",676.88],["nice",676.92],["surprise.",677.2]],"ipa":"/ðæt mʌst hæv bɪn ə naɪs sərˈpraɪz/"},{"start":678,"end":679,"text":"How's she doing?","words":[["How's",678],["she",678.16],["doing?",678.28]],"ipa":"/haʊz ʃi ˈduɪŋ/"},{"start":679,"end":680.28,"text":"She's doing well.","words":[["She's",679],["doing",679.28],["well.",679.6]],"ipa":"/ʃiz ˈduɪŋ wɛl/"},{"start":680.28,"end":684.16,"text":"She started a new job nearby, so we might have lunch next week.","words":[["She",680.28],["started",680.48],["a",680.92],["new",680.96],["job",681.24],["nearby,",681.6],["so",682.08],["we",682.4],["might",682.56],["have",682.8],["lunch",683],["next",683.24],["week.",683.52]],"ipa":"/ʃi ˈstɑrtɪd ə nu dʒɑb ˈnɪrˈbaɪ soʊ wi maɪt hæv lʌntʃ nɛkst wik/"},{"start":684.16,"end":685.12,"text":"What about you?","words":[["What",684.16],["about",684.32],["you?",684.52]],"ipa":"/wʌt əˈbaʊt ju/"},{"start":685.12,"end":687.08,"text":"Did you get everything done today?","words":[["Did",685.12],["you",685.32],["get",685.4],["everything",685.56],["done",685.92],["today?",686.16]],"ipa":"/dɪd ju ɡɛt ˈɛvriˌθɪŋ dʌn təˈdeɪ/"},{"start":687.08,"end":687.92,"text":"Most of it.","words":[["Most",687.08],["of",687.48],["it.",687.56]],"ipa":"/moʊst ʌv ɪt/"},{"start":687.92,"end":691.68,"text":"I've still got a couple of emails to answer, but they can wait until tomorrow.","words":[["I've",687.92],["still",688.08],["got",688.28],["a",688.44],["couple",688.48],["of",688.76],["emails",688.88],["to",689.24],["answer,",689.36],["but",689.72],["they",690.12],["can",690.28],["wait",690.44],["until",690.6],["tomorrow.",690.84]],"ipa":"/aɪv stɪl ɡɑt ə ˈkʌpəl ʌv iˈmeɪlz tu ˈænsər bʌt ðeɪ kæn weɪt ənˈtɪl təˈmɑˌroʊ/"},{"start":691.68,"end":693.68,"text":"I'm ready to switch off for a while.","words":[["I'm",691.68],["ready",691.88],["to",692.12],["switch",692.28],["off",692.64],["for",692.84],["a",692.96],["while.",693]],"ipa":"/aɪm ˈrɛdi tu swɪtʃ ɔf fɔr ə waɪl/"},{"start":693.68,"end":694.96,"text":"I don't blame you.","words":[["I",693.68],["don't",693.8],["blame",694.04],["you.",694.28]],"ipa":"/aɪ doʊnt bleɪm ju/"},{"start":694.96,"end":698.36,"text":"Want to grab a coffee or would that keep you awake tonight?","words":[["Want",694.96],["to",695.16],["grab",695.24],["a",695.48],["coffee",695.52],["or",696.04],["would",696.28],["that",696.44],["keep",696.68],["you",696.92],["awake",697.04],["tonight?",697.44]],"ipa":"/wɑnt tu ɡræb ə ˈkɑfi ɔr wʊd ðæt kip ju əˈweɪk təˈnaɪt/"},{"start":698.36,"end":702.24,"text":"Coffee would be a mistake, but I could definitely manage a sandwich.","words":[["Coffee",698.36],["would",698.76],["be",698.88],["a",699],["mistake,",699.08],["but",699.6],["I",699.8],["could",699.88],["definitely",700.04],["manage",700.4],["a",700.72],["sandwich.",700.76]],"ipa":"/ˈkɑfi wʊd bi ə mɪˈsteɪk bʌt aɪ kʊd ˈdɛfənətli ˈmænədʒ ə ˈsændwɪtʃ/"},{"start":702.24,"end":707.12,"text":"That's the end of our little example, and now I actually want a sandwich.","words":[["That's",702.24],["the",702.48],["end",702.6],["of",702.72],["our",702.8],["little",702.92],["example,",703.16],["and",703.72],["now",703.88],["I",704.44],["actually",704.6],["want",704.96],["a",705.08],["sandwich.",705.12]],"ipa":"/ðæts ðə ɛnd ʌv ˈaʊər ˈlɪtəl ɪɡˈzæmpəl ənd naʊ aɪ ˈækˌtʃuəli wɑnt ə ˈsændwɪtʃ/"},{"start":707.12,"end":709.2,"text":"We should have chosen a bookstore.","words":[["We",707.12],["should",707.28],["have",707.48],["chosen",707.64],["a",708],["bookstore.",708.08]],"ipa":"/wi ʃʊd hæv ˈtʃoʊzən ə ˈbʊkˌstɔr/"},{"start":709.2,"end":711.64,"text":"But notice where that conversation went.","words":[["But",709.2],["notice",709.4],["where",709.8],["that",710],["conversation",710.2],["went.",710.96]],"ipa":"/bʌt ˈnoʊtəs wɛr ðæt ˌkɑnvərˈseɪʃən wɛnt/"},{"start":711.64,"end":716.64,"text":"We started with work, talked about someone I knew, and ended up making a plan.","words":[["We",711.64],["started",711.84],["with",712.32],["work,",712.56],["talked",713.08],["about",713.44],["someone",713.72],["I",714.04],["knew,",714.12],["and",714.6],["ended",714.92],["up",715.2],["making",715.4],["a",715.72],["plan.",715.76]],"ipa":"/wi ˈstɑrtɪd wɪð wɝk tɔkt əˈbaʊt ˈsʌmˌwʌn aɪ nu ənd ˈɛndəd ʌp ˈmeɪkɪŋ ə plæn/"},{"start":716.64,"end":719.92,"text":"And you asked about me without making the change feel sudden.","words":[["And",716.64],["you",716.88],["asked",717.04],["about",717.28],["me",717.56],["without",717.8],["making",718.08],["the",718.4],["change",718.48],["feel",718.92],["sudden.",719.12]],"ipa":"/ənd ju æskt əˈbaʊt mi wɪˈθaʊt ˈmeɪkɪŋ ðə tʃeɪndʒ fil ˈsʌdən/"},{"start":719.92,"end":724.04,"text":"What about you fit because you'd finished telling me about your afternoon.","words":[["What",719.92],["about",720.08],["you",720.36],["fit",720.92],["because",721.28],["you'd",721.6],["finished",721.8],["telling",722.16],["me",722.48],["about",722.72],["your",722.96],["afternoon.",723.12]],"ipa":"/wʌt əˈbaʊt ju fɪt bɪˈkɔz jud ˈfɪnɪʃt ˈtɛlɪŋ mi əˈbaʊt jɔr ˌæftərˈnun/"},{"start":724.04,"end":727.2,"text":"You also gave me something honest to respond to.","words":[["You",724.04],["also",724.24],["gave",724.6],["me",724.84],["something",724.96],["honest",725.44],["to",726.04],["respond",726.16],["to.",726.6]],"ipa":"/ju ˈɔlsoʊ ɡeɪv mi ˈsʌmθɪŋ ˈɑnəst tu rɪˈspɑnd tu/"},{"start":727.2,"end":730.48,"text":"You had unfinished work, but you were ready to stop.","words":[["You",727.2],["had",727.4],["unfinished",727.68],["work,",728.32],["but",728.72],["you",729],["were",729.12],["ready",729.28],["to",729.52],["stop.",729.64]],"ipa":"/ju hæd ənˈfɪnɪʃt wɝk bʌt ju wɝ ˈrɛdi tu stɑp/"},{"start":730.48,"end":734.08,"text":"I could understand your mood without knowing every detail.","words":[["I",730.48],["could",730.6],["understand",730.76],["your",731.36],["mood",731.52],["without",731.92],["knowing",732.28],["every",732.68],["detail.",733.12]],"ipa":"/aɪ kʊd ˌʌndərˈstænd jɔr mud wɪˈθaʊt ˈnoʊɪŋ ˈɛvəri dɪˈteɪl/"},{"start":734.08,"end":735.68,"text":"That's useful when you're tired.","words":[["That's",734.08],["useful",734.32],["when",734.72],["you're",734.84],["tired.",734.96]],"ipa":"/ðæts ˈjusfəl wɛn jʊr ˈtaɪərd/"},{"start":735.68,"end":738.52,"text":"Your answer doesn't need to be a whole story every time.","words":[["Your",735.68],["answer",735.88],["doesn't",736.12],["need",736.4],["to",736.56],["be",736.64],["a",736.76],["whole",736.84],["story",737.12],["every",737.64],["time.",737.84]],"ipa":"/jɔr ˈænsər ˈdʌzənt nid tu bi ə hoʊl ˈstɔri ˈɛvəri taɪm/"},{"start":738.52,"end":742.36,"text":"Sometimes, long day, I'm glad to be home says plenty.","words":[["Sometimes,",738.52],["long",739.36],["day,",739.68],["I'm",740.2],["glad",740.32],["to",740.56],["be",740.6],["home",740.72],["says",741.32],["plenty.",741.56]],"ipa":"/səmˈtaɪmz lɔŋ deɪ aɪm ɡlæd tu bi hoʊm sɛz ˈplɛnti/"},{"start":742.36,"end":746.52,"text":"Especially if home is where you can finally let your shoulders drop.","words":[["Especially",742.36],["if",743.12],["home",743.32],["is",743.64],["where",743.8],["you",743.96],["can",744.08],["finally",744.32],["let",744.92],["your",745.16],["shoulders",745.32],["drop.",745.84]],"ipa":"/əˈspɛʃli ɪf hoʊm ɪz wɛr ju kæn ˈfaɪnəli lɛt jɔr ˈʃoʊldərz drɑp/"},{"start":746.52,"end":752.48,"text":"There's something kind about letting someone answer simply and trusting that more might come later.","words":[["There's",746.52],["something",746.72],["kind",747.12],["about",747.56],["letting",747.8],["someone",748.12],["answer",748.56],["simply",748.96],["and",749.76],["trusting",750],["that",750.48],["more",750.68],["might",751.04],["come",751.36],["later.",751.6]],"ipa":"/ðɛrz ˈsʌmθɪŋ kaɪnd əˈbaʊt ˈlɛtɪŋ ˈsʌmˌwʌn ˈænsər ˈsɪmpli ənd ˈtrʌstɪŋ ðæt mɔr maɪt kʌm ˈleɪtər/"},{"start":752.48,"end":755.16,"text":"I think about friends I haven't spoken to in a while.","words":[["I",752.48],["think",752.6],["about",752.8],["friends",753.04],["I",753.44],["haven't",753.48],["spoken",753.76],["to",754.12],["in",754.24],["a",754.32],["while.",754.4]],"ipa":"/aɪ θɪŋk əˈbaʊt frɛndz aɪ ˈhævənt ˈspoʊkən tu ɪn ə waɪl/"},{"start":755.16,"end":758.36,"text":"I sometimes wait until I've got big news before I call.","words":[["I",755.16],["sometimes",755.24],["wait",755.72],["until",755.92],["I've",756.16],["got",756.24],["big",756.48],["news",756.76],["before",757.12],["I",757.44],["call.",757.48]],"ipa":"/aɪ səmˈtaɪmz weɪt ənˈtɪl aɪv ɡɑt bɪɡ nuz bɪˈfɔr aɪ kɔl/"},{"start":758.36,"end":762.04,"text":"Then weeks go by and I miss all their ordinary days.","words":[["Then",758.36],["weeks",758.92],["go",759.24],["by",759.4],["and",759.8],["I",759.96],["miss",760],["all",760.32],["their",760.52],["ordinary",760.72],["days.",761.2]],"ipa":"/ðɛn wiks ɡoʊ baɪ ənd aɪ mɪs ɔl ðɛr ˈɔrdəˌnɛri deɪz/"},{"start":762.04,"end":763.32,"text":"I do that, too.","words":[["I",762.04],["do",762.2],["that,",762.36],["too.",762.6]],"ipa":"/aɪ du ðæt tu/"},{"start":763.32,"end":768.36,"text":"But when a friend calls to tell me their dog stole a piece of toast, I'm delighted.","words":[["But",763.32],["when",763.52],["a",763.64],["friend",763.72],["calls",764.08],["to",764.52],["tell",764.64],["me",764.84],["their",765],["dog",765.2],["stole",765.64],["a",766.04],["piece",766.12],["of",766.36],["toast,",766.48],["I'm",767.28],["delighted.",767.48]],"ipa":"/bʌt wɛn ə frɛnd kɔlz tu tɛl mi ðɛr dɔɡ stoʊl ə pis ʌv toʊst aɪm dɪˈlaɪtəd/"},{"start":768.36,"end":770.64,"text":"I get a tiny picture of their life.","words":[["I",768.36],["get",768.48],["a",768.64],["tiny",768.72],["picture",769.16],["of",769.52],["their",769.64],["life.",769.8]],"ipa":"/aɪ ɡɛt ə ˈtaɪni ˈpɪktʃər ʌv ðɛr laɪf/"},{"start":770.64,"end":774.28,"text":"And probably a picture of the dog looking completely innocent.","words":[["And",770.64],["probably",770.84],["a",771.28],["picture",771.32],["of",771.68],["the",771.8],["dog",771.92],["looking",772.32],["completely",772.56],["innocent.",773.32]],"ipa":"/ənd ˈprɑbəˌbli ə ˈpɪktʃər ʌv ðə dɔɡ ˈlʊkɪŋ kəmˈplitli ˈɪnəsənt/"},{"start":774.28,"end":778.84,"text":"Those little stories help you feel close even when you live far apart. They do.","words":[["Those",774.28],["little",774.52],["stories",774.72],["help",775.12],["you",775.32],["feel",775.4],["close",775.6],["even",776.16],["when",776.4],["you",776.56],["live",776.64],["far",776.84],["apart.",777.04],["They",777.88],["do.",778.04]],"ipa":"/ðoʊz ˈlɪtəl ˈstɔriz hɛlp ju fil kloʊs ˈivɪn wɛn ju laɪv fɑr əˈpɑrt ðeɪ du/"},{"start":778.84,"end":783.8,"text":"So if you're practicing English today, you could send someone a short voice message.","words":[["So",778.84],["if",779.08],["you're",779.28],["practicing",779.56],["English",780.16],["today,",780.6],["you",781.24],["could",781.44],["send",781.64],["someone",781.96],["a",782.4],["short",782.48],["voice",782.8],["message.",783.12]],"ipa":"/soʊ ɪf jʊr ˈpræktəsɪŋ ˈɪŋɡlɪʃ təˈdeɪ ju kʊd sɛnd ˈsʌmˌwʌn ə ʃɔrt vɔɪs ˈmɛsədʒ/"},{"start":783.8,"end":787.4,"text":"Share one thing that happened and ask how their day went.","words":[["Share",783.8],["one",784.16],["thing",784.48],["that",784.76],["happened",784.92],["and",785.44],["ask",785.64],["how",785.96],["their",786.08],["day",786.32],["went.",786.48]],"ipa":"/ʃɛr wʌn θɪŋ ðæt ˈhæpənd ənd æsk haʊ ðɛr deɪ wɛnt/"},{"start":787.4,"end":789.52,"text":"Give them room to answer when they can.","words":[["Give",787.4],["them",787.56],["room",787.76],["to",787.96],["answer",788.08],["when",788.44],["they",788.6],["can.",788.72]],"ipa":"/ɡɪv ðɛm rum tu ˈænsər wɛn ðeɪ kæn/"},{"start":789.52,"end":793.12,"text":"And if a word goes missing while you're speaking, explain it another way.","words":[["And",789.52],["if",789.76],["a",789.84],["word",789.92],["goes",790.16],["missing",790.4],["while",790.76],["you're",790.88],["speaking,",791],["explain",791.64],["it",792.04],["another",792.16],["way.",792.44]],"ipa":"/ənd ɪf ə wɝd ɡoʊz ˈmɪsɪŋ waɪl jʊr ˈspikɪŋ ɪkˈspleɪn ɪt əˈnʌðər weɪ/"},{"start":793.12,"end":795.36,"text":"The person listening can still follow you.","words":[["The",793.12],["person",793.24],["listening",793.6],["can",793.96],["still",794.12],["follow",794.36],["you.",794.68]],"ipa":"/ðə ˈpɝsən ˈlɪsənɪŋ kæn stɪl ˈfɑloʊ ju/"},{"start":795.36,"end":800.64,"text":"You might say something imperfectly and still make someone laugh, help them feel understood,","words":[["You",795.36],["might",795.52],["say",795.8],["something",796],["imperfectly",796.48],["and",797.44],["still",797.68],["make",798],["someone",798.24],["laugh,",798.6],["help",799.12],["them",799.32],["feel",799.48],["understood,",799.76]],"ipa":"/ju maɪt seɪ ˈsʌmθɪŋ ˌɪmˈpɝfɪktli ənd stɪl meɪk ˈsʌmˌwʌn læf hɛlp ðɛm fil ˌʌndərˈstʊd/"},{"start":800.64,"end":804.32,"text":"or discover that you've both had the same kind of afternoon.","words":[["or",800.64],["discover",800.88],["that",801.4],["you've",801.6],["both",801.8],["had",802.16],["the",802.44],["same",802.56],["kind",802.96],["of",803.16],["afternoon.",803.24]],"ipa":"/ɔr dɪˈskʌvər ðæt juv boʊθ hæd ðə seɪm kaɪnd ʌv ˌæftərˈnun/"},{"start":804.32,"end":806.44,"text":"Those are good reasons to keep trying.","words":[["Those",804.32],["are",804.48],["good",804.56],["reasons",804.84],["to",805.24],["keep",805.36],["trying.",805.56]],"ipa":"/ðoʊz ɑr ɡʊd ˈrizənz tu kip ˈtraɪɪŋ/"},{"start":806.44,"end":812.76,"text":"Tomorrow will bring another small story, another question, and another chance to get a little more comfortable speaking.","words":[["Tomorrow",806.44],["will",806.88],["bring",807.04],["another",807.36],["small",807.72],["story,",808.08],["another",808.72],["question,",809.04],["and",809.72],["another",809.84],["chance",810.12],["to",810.48],["get",810.6],["a",810.84],["little",810.92],["more",811.24],["comfortable",811.44],["speaking.",811.88]],"ipa":"/təˈmɑˌroʊ wɪl brɪŋ əˈnʌðər smɔl ˈstɔri əˈnʌðər ˈkwɛstʃən ənd əˈnʌðər tʃæns tu ɡɛt ə ˈlɪtəl mɔr ˈkʌmfərtəbəl ˈspikɪŋ/"},{"start":812.76,"end":815.64,"text":"Thanks for spending part of your day with us at Mr.","words":[["Thanks",812.76],["for",813],["spending",813.16],["part",813.6],["of",813.84],["your",813.92],["day",814.04],["with",814.36],["us",814.64],["at",814.96],["Mr.",815.16]],"ipa":"/θæŋks fɔr ˈspɛndɪŋ pɑrt ʌv jɔr deɪ wɪð ʌs æt ˈmɪstər/"},{"start":815.64,"end":819.24,"text":"English Channel, where learning English is easy and fun.","words":[["English",815.64],["Channel,",816],["where",816.72],["learning",816.96],["English",817.36],["is",817.8],["easy",818.04],["and",818.44],["fun.",818.64]],"ipa":"/ˈɪŋɡlɪʃ ˈtʃænəl wɛr ˈlɝnɪŋ ˈɪŋɡlɪʃ ɪz ˈizi ənd fʌn/"},{"start":819.24,"end":823.8,"text":"Take care of yourselves and keep sharing those everyday moments. Bye everyone.","words":[["Take",819.24],["care",819.48],["of",819.64],["yourselves",819.72],["and",820.36],["keep",820.52],["sharing",820.8],["those",821.16],["everyday",821.44],["moments.",821.88],["Bye",822.64],["everyone.",822.84]],"ipa":"/teɪk kɛr ʌv jʊrˈsɛlvz ənd kip ˈʃɛrɪŋ ðoʊz ˈɛvriˈdeɪ ˈmoʊmənts baɪ ˈɛvriˌwʌn/"},{"start":823.8,"end":825.08,"text":"Thanks for listening everyone.","words":[["Thanks",823.8],["for",824],["listening",824.12],["everyone.",824.44]],"ipa":"/θæŋks fɔr ˈlɪsənɪŋ ˈɛvriˌwʌn/"},{"start":825.08,"end":830.2,"text":"Have a good rest of your day and we'll see you next time. Goodbye.","words":[["Have",825.08],["a",825.24],["good",825.32],["rest",825.6],["of",825.84],["your",825.88],["day",826],["and",826.32],["we'll",826.52],["see",826.64],["you",826.84],["next",826.92],["time.",827.2],["Goodbye.",827.8]],"ipa":"/hæv ə ɡʊd rɛst ʌv jɔr deɪ ənd wil si ju nɛkst taɪm ˌɡʊdˈbaɪ/"}]`),i=[{level:"B1",group:"Kể chuyện trong ngày",order:21},{level:"B2",group:"Hội thoại thực tế",order:20}],u={id:t,youtubeId:e,title:a,channel:n,level:"A2",group:o,order:18,duration:837,captions:r,segments:s,also:i};export{i as also,r as captions,n as channel,u as default,h as duration,o as group,t as id,d as level,l as order,s as segments,a as title,e as youtubeId};
